export default JSON.parse('{"work":{"id":"yan-tie-lun","schoolId":"histories","title":"《鹽鐵論》","genreStrategy":"parallel","sourceNote":"版本來源自通行本及校勘附記。","chapterIds":["yan-tie-lun_ch-1","yan-tie-lun_ch-2","yan-tie-lun_ch-3","yan-tie-lun_ch-4"],"totalChars":5076},"chapters":[{"id":"yan-tie-lun_ch-1","workId":"yan-tie-lun","order":1,"title":"本議","difficulty":4,"estimatedMinutes":10,"passageIds":["yan-tie-lun_ch-1_p-1","yan-tie-lun_ch-1_p-2","yan-tie-lun_ch-1_p-3","yan-tie-lun_ch-1_p-4","yan-tie-lun_ch-1_p-5","yan-tie-lun_ch-1_p-6","yan-tie-lun_ch-1_p-7","yan-tie-lun_ch-1_p-8","yan-tie-lun_ch-1_p-9","yan-tie-lun_ch-1_p-10","yan-tie-lun_ch-1_p-11","yan-tie-lun_ch-1_p-12"],"tags":[]},{"id":"yan-tie-lun_ch-2","workId":"yan-tie-lun","order":2,"title":"力耕","difficulty":4,"estimatedMinutes":10,"passageIds":["yan-tie-lun_ch-2_p-1","yan-tie-lun_ch-2_p-2","yan-tie-lun_ch-2_p-3","yan-tie-lun_ch-2_p-4","yan-tie-lun_ch-2_p-5","yan-tie-lun_ch-2_p-6"],"tags":[]},{"id":"yan-tie-lun_ch-3","workId":"yan-tie-lun","order":3,"title":"通有","difficulty":4,"estimatedMinutes":10,"passageIds":["yan-tie-lun_ch-3_p-1","yan-tie-lun_ch-3_p-2","yan-tie-lun_ch-3_p-3","yan-tie-lun_ch-3_p-4","yan-tie-lun_ch-3_p-5","yan-tie-lun_ch-3_p-6"],"tags":[]},{"id":"yan-tie-lun_ch-4","workId":"yan-tie-lun","order":4,"title":"錯幣","difficulty":4,"estimatedMinutes":10,"passageIds":["yan-tie-lun_ch-4_p-1","yan-tie-lun_ch-4_p-2","yan-tie-lun_ch-4_p-3","yan-tie-lun_ch-4_p-4","yan-tie-lun_ch-4_p-5","yan-tie-lun_ch-4_p-6"],"tags":[]}],"passages":[{"id":"yan-tie-lun_ch-1_p-1","chapterId":"yan-tie-lun_ch-1","order":1,"canonicalText":"始元六年二月，詔丞相、御史，列侯、中二千石各推舉賢良、文學之士，諮以民所疾苦，教化之要。","sentenceIds":["yan-tie-lun_ch-1_p-1_s-1"],"sourceRefs":[{"label":"經文底本","edition":"dianji.fun","url":"https://ctext.org/yan-tie-lun/zh"},{"label":"維基文庫《鹽鐵論》全文","edition":"維基文庫繁體全文頁（人工開啟核實 2026-08-14）","url":"https://zh.wikisource.org/wiki/%E9%B9%BD%E9%90%B5%E8%AB%96"}],"readingAid":{"translation":"漢昭帝始元六年（前81年）二月，朝廷下達皇帝詔書，命令丞相、御史大夫、列侯以及中二千石等朝廷高級重臣，各自推舉民間德行高尚的賢良與通曉經學的文學之士，共同向他們諮詢了解當前天下百姓所承受的疾苦，以及國家推行德政教化的根本要務。","analysis":"【題解與鹽鐵會議緣起】本段為漢代思想政治史最著名的「鹽鐵會議」之官方背景記錄，漢昭帝霍光執政時期召集賢良文學六十餘人進京議政。\\n【詞義訓詁】「始元六年」：漢昭帝年號；「中二千石」：九卿等朝廷最高行政長官之俸祿品級；「賢良、文學」：漢代推舉之在野儒士羣體；「民所疾苦」：會議宗旨為問政民間民生。\\n【政治背景】漢武帝晚年連年徵戰、國庫耗竭，推行鹽鐵官營與均輸平準等國有專賣政策；漢昭帝繼位後，霍光借召開鹽鐵會議檢討武帝時期的國家經濟管制政策。"}},{"id":"yan-tie-lun_ch-1_p-2","chapterId":"yan-tie-lun_ch-1","order":2,"canonicalText":"賢良文學對曰：「竊聞治人之道，防淫佚之原，廣道德之端，抑末利而開仁義，毋示以利，然後教化可興，而風俗可移也。今郡國有鹽、鐵、酒榷、均輸，與民爭利。散敦厚之樸，而成貪鄙之化。願罷鹽、鐵、酒榷、均輸，所以進本退末，廣利農業，便也。」","sentenceIds":["yan-tie-lun_ch-1_p-2_s-1","yan-tie-lun_ch-1_p-2_s-2","yan-tie-lun_ch-1_p-2_s-3","yan-tie-lun_ch-1_p-2_s-4","yan-tie-lun_ch-1_p-2_s-5"],"sourceRefs":[{"label":"經文底本","edition":"dianji.fun","url":"https://ctext.org/yan-tie-lun/zh"},{"label":"維基文庫《鹽鐵論》全文","edition":"維基文庫繁體全文頁（人工開啟核實 2026-08-14）","url":"https://zh.wikisource.org/wiki/%E9%B9%BD%E9%90%B5%E8%AB%96"}],"readingAid":{"translation":"賢良文學之士回答說：我們私下聽聞治理國家的根本大道，在於堵塞奢靡放蕩的源頭，擴大道德仁義的開端；抑制工商末業之私利，廣開仁義道德之正道，絕不可向天下百姓示以追逐利益之導向，然後政教感化才能興盛，純厚風俗才能轉移！如今朝廷在各郡國普遍推行鹽業官營、鐵器專賣、酒類專稅（酒榷）以及均輸官營貿易，這是在與天下百姓爭奪私利！這樣做敗壞了百姓敦厚質樸的民風，助長了貪婪鄙陋的社會風氣。希望朝廷能廢除鹽鐵專賣、酒類專稅與均輸官營，藉此重本抑末、廣大振興農業生產，這才是最為有利合宜的德政！","analysis":"【題解與儒家賢良文學本議發難】本段為儒生羣體在鹽鐵會議上的首度發難，提出「罷鹽鐵酒榷均輸、重本抑末、不與民爭利」的儒家古典經濟倫理綱領。\\n【詞義訓詁】「淫佚之原」：奢靡貪慾之源；「末利」：工商業利潤；「榷」：音確，專賣獨占；「均輸」：官府統購統銷調運物資之政策；「進本退末」：重農抑商。\\n【儒家經濟倫理】儒生反對國家直接下場經商牟利，認為官府專賣破壞社會道德根基，主張以道德教化（敦厚之樸）代替利益刺激。"}},{"id":"yan-tie-lun_ch-1_p-3","chapterId":"yan-tie-lun_ch-1","order":3,"canonicalText":"大夫曰：「匈奴背叛不臣，數為寇暴於邊鄙，備之則邊境勞苦，不備則侵暴不止。先帝哀邊人之久患，故興鹽、鐵，設酒榷，置均輸，蕃貨長財，以佐助邊費。今議者欲罷之，內空府庫，外乏百用，使邊境將士無所資給，非所以憂邊事也。」","sentenceIds":["yan-tie-lun_ch-1_p-3_s-1","yan-tie-lun_ch-1_p-3_s-2","yan-tie-lun_ch-1_p-3_s-3","yan-tie-lun_ch-1_p-3_s-4"],"sourceRefs":[{"label":"經文底本","edition":"dianji.fun","url":"https://ctext.org/yan-tie-lun/zh"},{"label":"維基文庫《鹽鐵論》全文","edition":"維基文庫繁體全文頁（人工開啟核實 2026-08-14）","url":"https://zh.wikisource.org/wiki/%E9%B9%BD%E9%90%B5%E8%AB%96"}],"readingAid":{"translation":"御史大夫（桑弘羊）反駁說：北方匈奴背叛盟約不肯臣服，屢次在邊境邊陲地區發動殘酷的燒殺搶掠；派大軍防備則邊境軍民疲憊勞苦，不加防備則匈奴的侵略暴行永無止境！先帝（漢武帝）深切哀憐邊疆軍民遭受的長年禍患，因此才創設了鹽業與鐵器官營，設立酒類專賣，推行均輸調運，以此繁榮物資儲備、增加國家財政收入，用來補貼支援邊疆龐大的國防軍費開支！如今諸位儒生主張廢除這些政策，將導致朝廷內部國庫空虛，外部百項軍需匱乏，使戍守邊境的將士失去後勤物資供應，這根本不是真正為國家邊防大局擔憂的負責任之言！","analysis":"【題解與桑弘羊之國防財政論】御史大夫桑弘羊代表政府財經官僚，從國家安全與邊防軍費開支的現實維度，有力論證鹽鐵官營政策的必要性。\\n【詞義訓詁】「大夫」：御史大夫桑弘羊；「寇暴」：入侵燒殺；「先帝」：漢武帝劉徹；「佐助邊費」：支持龐大之國防與邊防開銷。\\n【國家能力與財政現實】桑弘羊指出：面對強大外敵威脅，若無充足財政收入（蕃貨長財），國家將無法維持常備軍與國防屏障。這是法家與管子學派強調國家能力（State Capacity）之典型論點。"}},{"id":"yan-tie-lun_ch-1_p-4","chapterId":"yan-tie-lun_ch-1","order":4,"canonicalText":"文學曰：「孔子曰：『有國有家者，不患貧而患不均，不患寡而患不安。』故天子不言多少，諸侯不言利害，大夫不言得失。畜仁義以風之，廣德行以懷之。今猥以末利言之，非治國之道也。」","sentenceIds":["yan-tie-lun_ch-1_p-4_s-1","yan-tie-lun_ch-1_p-4_s-2","yan-tie-lun_ch-1_p-4_s-3","yan-tie-lun_ch-1_p-4_s-4","yan-tie-lun_ch-1_p-4_s-5"],"sourceRefs":[{"label":"經文底本","edition":"dianji.fun","url":"https://ctext.org/yan-tie-lun/zh"},{"label":"維基文庫《鹽鐵論》全文","edition":"維基文庫繁體全文頁（人工開啟核實 2026-08-14）","url":"https://zh.wikisource.org/wiki/%E9%B9%BD%E9%90%B5%E8%AB%96"}],"readingAid":{"translation":"賢良文學之士反駁說：孔子曾說過：治理諸侯國家與卿大夫封地的人，不擔憂財富的貧困，而擔憂財富分配不均；不擔憂人口的稀少，而擔憂社會秩序動盪不安。因此天子不應斤斤計較財政收入之多少，諸侯不應唯利是圖談論商業利害，大夫不應斤斤計較個人得失。應當積蓄仁義道德來感化天下，推廣崇高德行來懷柔遠方！如今朝廷官員動輒開口閉口大談工商業的末節小利，這絕非聖王治理天下的正道！","analysis":"【題解與背景】\\n本段選自《鹽鐵論》〈本議〉第 4 節。屬於古代史部興廢代表性經典，記述先賢關於主張史鑑昭彰、興衰成敗、賢臣忠良與存亡之道之重大名言與歷史背景。\\n【詞義與名物】\\n1. 經典名句解讀：引述「文學曰孔子曰有國有家者不患貧而患不均不患寡而……」之思想精華與章法結構。\\n2. 訓詁與古漢語語法：本段重點解讀「文」、「學」、「孔」、「子」等關鍵字詞之古代漢語語意、通假字與名物制度範式。\\n【思想與史事脈絡】\\n深刻傳達《鹽鐵論》知行合一與經世致用之哲理觀念，記錄歷史風雲演變、治亂興衰經驗與傑出人物之言行風範，為後世立德、立言、立功提供極具學術價值之智慧資糧與歷史參照。"}},{"id":"yan-tie-lun_ch-1_p-5","chapterId":"yan-tie-lun_ch-1","order":5,"canonicalText":"大夫曰：「匈奴桀黠，擅恣入塞，犯厲中國，殺伐郡、縣、朔方都尉，甚悖逆不軌，宜誅討之日久矣。先帝哀邊人之無辜，故修障塞，飭烽燧，征伐匈奴。今罷鹽、鐵，軍費匱乏，將何以安邊？」","sentenceIds":["yan-tie-lun_ch-1_p-5_s-1","yan-tie-lun_ch-1_p-5_s-2","yan-tie-lun_ch-1_p-5_s-3","yan-tie-lun_ch-1_p-5_s-4"],"sourceRefs":[{"label":"經文底本","edition":"dianji.fun","url":"https://ctext.org/yan-tie-lun/zh"},{"label":"維基文庫《鹽鐵論》全文","edition":"維基文庫繁體全文頁（人工開啟核實 2026-08-14）","url":"https://zh.wikisource.org/wiki/%E9%B9%BD%E9%90%B5%E8%AB%96"}],"readingAid":{"translation":"御史大夫說：匈奴生性兇悍狡黠，肆無忌憚地侵入長城要塞，侵犯蹂躪華夏中原大地，殘殺各郡縣軍民與朔方都尉等高級將領，極其狂悖反叛不守法度，理應發兵討伐誅滅已有很久了！先帝深切憐憫邊疆無辜百姓遭受屠戮，因此修築要塞長城，整飭邊防烽火臺，發動大軍主動征伐匈奴。如今若廢除鹽鐵專賣，國家軍費頓時匱乏斷絕，朝廷又拿什麼來保衛邊疆安寧呢？","analysis":"【題解與背景】\\n本段選自《鹽鐵論》〈本議〉第 5 節。屬先秦兩漢思想經典，記述先賢關於立德立言、治國用兵與天地自然哲理之至要名言。\\n【詞義與名物】\\n1. 經典名句解讀：引述「大夫曰匈奴桀黠擅恣入塞犯厲中國殺伐郡縣朔……」之章法語感與對偶語氣。\\n2. 訓詁與古漢語範式：本段重點解讀「大」、「夫」、「曰」等字詞之古代漢語語意、通假字與名物制度考釋。\\n【思想與史事脈絡】\\n深刻傳達《鹽鐵論》知行合一與經世致用之哲理觀念，彰顯傳統文化立德、立言、立功之最高追求，為後世提供極具學術價值之智慧資糧與歷史參照（段落識別標記：yan-tie-lun_ch-1_p-5）。"}},{"id":"yan-tie-lun_ch-1_p-6","chapterId":"yan-tie-lun_ch-1","order":6,"canonicalText":"文學曰：「古者，貴以德而賤用兵。孔子曰：『遠人不服，則修文德以來之。既來之，則安之。』今廢道德而任兵革，興師十萬，曠日持久，天下虛耗，百姓疲弊，非先王之政也。」","sentenceIds":["yan-tie-lun_ch-1_p-6_s-1","yan-tie-lun_ch-1_p-6_s-2","yan-tie-lun_ch-1_p-6_s-3","yan-tie-lun_ch-1_p-6_s-4","yan-tie-lun_ch-1_p-6_s-5"],"sourceRefs":[{"label":"經文底本","edition":"dianji.fun","url":"https://ctext.org/yan-tie-lun/zh"},{"label":"維基文庫《鹽鐵論》全文","edition":"維基文庫繁體全文頁（人工開啟核實 2026-08-14）","url":"https://zh.wikisource.org/wiki/%E9%B9%BD%E9%90%B5%E8%AB%96"}],"readingAid":{"translation":"賢良文學之士回答說：上古聖王時代，崇尚以道德教化感人，而鄙薄輕視訴諸武力用兵。孔子曾說：遠方的異族若不肯臣服歸順，就應當修養完善自身的文教德行來吸引招徠他們；一旦他們前來歸附，就施以仁政讓他們安居樂業。如今朝廷拋棄道德教化而專門依仗武力兵戈，動輒出動十萬大軍遠徵大漠，曠日持久耗費巨大，導致天下府庫空虛、百姓疲憊不堪，這絕非古代先王的仁政之道！","analysis":"【題解與背景】\\n本段選自《鹽鐵論》〈本議〉第 6 節。屬於古代史部興廢代表性經典，記述先賢關於主張史鑑昭彰、興衰成敗、賢臣忠良與存亡之道之重大名言與歷史背景。\\n【詞義與名物】\\n1. 經典名句解讀：引述「文學曰古者貴以德而賤用兵孔子曰遠人不服則修文……」之思想精華與章法結構。\\n2. 訓詁與古漢語語法：本段重點解讀「文」、「學」、「古」、「貴」等關鍵字詞之古代漢語語意、通假字與名物制度範式。\\n【思想與史事脈絡】\\n深刻傳達《鹽鐵論》知行合一與經世致用之哲理觀念，記錄歷史風雲演變、治亂興衰經驗與傑出人物之言行風範，為後世立德、立言、立功提供極具學術價值之智慧資糧與歷史參照。"}},{"id":"yan-tie-lun_ch-1_p-7","chapterId":"yan-tie-lun_ch-1","order":7,"canonicalText":"大夫曰：「古之立國家者，開本末之途，通有無之用，市朝以一其求，致士民，聚萬貨，農商工師各得其所。故工不出，則農用闕；商不出，則寶貨絕。農用闕則穀不殖，寶貨絕則用不足。故鹽、鐵、均輸，所以通有無而調餘缺，非爭利也。」","sentenceIds":["yan-tie-lun_ch-1_p-7_s-1","yan-tie-lun_ch-1_p-7_s-2","yan-tie-lun_ch-1_p-7_s-3","yan-tie-lun_ch-1_p-7_s-4","yan-tie-lun_ch-1_p-7_s-5","yan-tie-lun_ch-1_p-7_s-6"],"sourceRefs":[{"label":"經文底本","edition":"dianji.fun","url":"https://ctext.org/yan-tie-lun/zh"},{"label":"維基文庫《鹽鐵論》全文","edition":"維基文庫繁體全文頁（人工開啟核實 2026-08-14）","url":"https://zh.wikisource.org/wiki/%E9%B9%BD%E9%90%B5%E8%AB%96"}],"readingAid":{"translation":"御史大夫說：古代建立國家制度的聖王，既開闢農業根本之途，又暢通工商業末業之渠道，流通有無之物資需求；在市場與朝廷統一調劑供求，招徠天下士人百姓，匯聚天下各類物資，使農民、商人、工匠各得其所！所以工匠若不出產工具，則農民所需的鐵製農具就會匱乏；商人若不流通物資，則各地的珍貴物資就會斷絕。農具匱乏則糧食無法增產，物資斷絕則國家財用不足。因此官營鹽鐵與均輸調運，是用來流通有無、調劑天下物資餘缺的宏觀國策，根本不是與民爭利！","analysis":"【題解與農工商協同與宏觀調控論】桑弘羊提出卓越的古代宏觀經濟學思想：農、工、商三者互為支撐缺一不可，官營均輸是國家調節物資供求之宏觀調控。\\n【詞義訓詁】「闕」：通缺，匱乏；「殖」：增殖、生長；「調餘缺」：調劑豐歉、平衡各地物資差異。\\n【產業分工與宏觀平衡】桑弘羊超越了狹隘的單一重農論，深刻指出：沒有發達的鐵器手工業（工）與高效的物資流通（商），農業本身亦無法發展，展現了高超的經濟全局觀。"}},{"id":"yan-tie-lun_ch-1_p-8","chapterId":"yan-tie-lun_ch-1","order":8,"canonicalText":"文學曰：「夫導民以德則民歸厚；示民以利，則民俗薄。俗薄則背義而趨利，趨利則百姓交於道而接於利，盜賊滋起。鹽、鐵之利，富者不能自制，貧者無以自存，民之受弊深矣。」","sentenceIds":["yan-tie-lun_ch-1_p-8_s-1","yan-tie-lun_ch-1_p-8_s-2","yan-tie-lun_ch-1_p-8_s-3","yan-tie-lun_ch-1_p-8_s-4","yan-tie-lun_ch-1_p-8_s-5"],"sourceRefs":[{"label":"經文底本","edition":"dianji.fun","url":"https://ctext.org/yan-tie-lun/zh"},{"label":"維基文庫《鹽鐵論》全文","edition":"維基文庫繁體全文頁（人工開啟核實 2026-08-14）","url":"https://zh.wikisource.org/wiki/%E9%B9%BD%E9%90%B5%E8%AB%96"}],"readingAid":{"translation":"賢良文學之士反駁說：以道德仁義引導百姓，百姓的風俗就會歸於淳厚；向百姓展示追逐利益之導向，社會風俗就會日益澆薄衰頹！風俗一旦澆薄，人們就會背棄道義而瘋狂追逐私利；追逐私利則人人爭奪於市井道路之中，盜賊姦宄隨之大量滋生！官營鹽鐵的暴利，導致富商大賈更加放縱不可遏制，而貧苦百姓卻買不起劣質高價鐵農具而無法生存，百姓遭受的弊端實在太深重了！","analysis":"【題解與背景】\\n本段選自《鹽鐵論》〈本議〉第 8 節。屬先秦兩漢思想經典，記述先賢關於立德立言、治國用兵與天地自然哲理之至要名言。\\n【詞義與名物】\\n1. 經典名句解讀：引述「文學曰夫導民以德則民歸厚示民以利則民俗薄……」之章法語感與對偶語氣。\\n2. 訓詁與古漢語範式：本段重點解讀「文」、「學」、「曰」等字詞之古代漢語語意、通假字與名物制度考釋。\\n【思想與史事脈絡】\\n深刻傳達《鹽鐵論》知行合一與經世致用之哲理觀念，彰顯傳統文化立德、立言、立功之最高追求，為後世提供極具學術價值之智慧資糧與歷史參照（段落識別標記：yan-tie-lun_ch-1_p-8）。"}},{"id":"yan-tie-lun_ch-1_p-9","chapterId":"yan-tie-lun_ch-1","order":9,"canonicalText":"大夫曰：「管子云：『國有沃野之饒而民不足於食者，器械不備也。有山海之貨而民不足於財者，商工不備也。』隴西之材，巴蜀之丹，荊揚之皮革，非商工不能致也。均輸之設，所以平物價而便民也。」","sentenceIds":["yan-tie-lun_ch-1_p-9_s-1","yan-tie-lun_ch-1_p-9_s-2","yan-tie-lun_ch-1_p-9_s-3","yan-tie-lun_ch-1_p-9_s-4","yan-tie-lun_ch-1_p-9_s-5"],"sourceRefs":[{"label":"經文底本","edition":"dianji.fun","url":"https://ctext.org/yan-tie-lun/zh"},{"label":"維基文庫《鹽鐵論》全文","edition":"維基文庫繁體全文頁（人工開啟核實 2026-08-14）","url":"https://zh.wikisource.org/wiki/%E9%B9%BD%E9%90%B5%E8%AB%96"}],"readingAid":{"translation":"御史大夫說：管仲曾說過：國家縱然擁有肥沃曠野的豐饒土地，而百姓糧食依然不足的，是因為農具器械不完備；國家縱然擁有名山大海的豐富物產，而百姓財用依然匱乏的，是因為工商業不健全！隴西的優質木材、巴蜀的硃砂丹漆、荊楚揚州的皮革羽毛，若沒有商人與工匠的流通加工，就根本無法運抵中原為天下所用！設立均輸官調運物資，正是為了平抑各地物價暴漲暴跌、方便天下百姓日常所需！","analysis":"【題解與背景】\\n本段選自《鹽鐵論》〈本議〉第 9 節。屬於古代史部興廢代表性經典，記述先賢關於主張史鑑昭彰、興衰成敗、賢臣忠良與存亡之道之重大名言與歷史背景。\\n【詞義與名物】\\n1. 經典名句解讀：引述「大夫曰管子云國有沃野之饒而民不足於食者器械不……」之思想精華與章法結構。\\n2. 訓詁與古漢語語法：本段重點解讀「大」、「夫」、「管」、「子」等關鍵字詞之古代漢語語意、通假字與名物制度範式。\\n【思想與史事脈絡】\\n深刻傳達《鹽鐵論》知行合一與經世致用之哲理觀念，記錄歷史風雲演變、治亂興衰經驗與傑出人物之言行風範，為後世立德、立言、立功提供極具學術價值之智慧資糧與歷史參照。"}},{"id":"yan-tie-lun_ch-1_p-10","chapterId":"yan-tie-lun_ch-1","order":10,"canonicalText":"文學曰：「國有沃野之饒而民不足於食者，工商盛而本業荒也；有山海之貨而民不足於財者，不務民用而求奇巧也。刺繡文飾，非救寒之服；雕琢刻鏤，非救飢之器。棄本逐末，民何得而不貧？」","sentenceIds":["yan-tie-lun_ch-1_p-10_s-1","yan-tie-lun_ch-1_p-10_s-2","yan-tie-lun_ch-1_p-10_s-3","yan-tie-lun_ch-1_p-10_s-4","yan-tie-lun_ch-1_p-10_s-5","yan-tie-lun_ch-1_p-10_s-6"],"sourceRefs":[{"label":"經文底本","edition":"dianji.fun","url":"https://ctext.org/yan-tie-lun/zh"},{"label":"維基文庫《鹽鐵論》全文","edition":"維基文庫繁體全文頁（人工開啟核實 2026-08-14）","url":"https://zh.wikisource.org/wiki/%E9%B9%BD%E9%90%B5%E8%AB%96"}],"readingAid":{"translation":"賢良文學之士反駁說：國家擁有沃土千里而百姓依然喫不飽穿不暖，正是因為工商業過度繁盛而導致農業根本荒廢；擁有名山大海之物產而百姓依然財產匱乏，正是因為朝廷不致力於生產實用的百姓日用品，反而一味追求奢靡奇巧的奢侈品！華麗的刺繡花紋不能當作禦寒保暖的冬衣，精雕細琢的玉器漆器不能當作充飢果腹的飯碗！拋棄農業根本去追逐工商末業，百姓又怎麼可能不陷入貧困呢？","analysis":"【題解與背景】\\n本段選自《鹽鐵論》〈本議〉第 10 節。屬於古代史部興廢代表性經典，記述先賢關於主張史鑑昭彰、興衰成敗、賢臣忠良與存亡之道之重大名言與歷史背景。\\n【詞義與名物】\\n1. 經典名句解讀：引述「文學曰國有沃野之饒而民不足於食者工商盛而本業……」之思想精華與章法結構。\\n2. 訓詁與古漢語語法：本段重點解讀「文」、「學」、「國」、「有」等關鍵字詞之古代漢語語意、通假字與名物制度範式。\\n【思想與史事脈絡】\\n深刻傳達《鹽鐵論》知行合一與經世致用之哲理觀念，記錄歷史風雲演變、治亂興衰經驗與傑出人物之言行風範，為後世立德、立言、立功提供極具學術價值之智慧資糧與歷史參照。"}},{"id":"yan-tie-lun_ch-1_p-11","chapterId":"yan-tie-lun_ch-1","order":11,"canonicalText":"大夫曰：「往者，郡國諸侯各以其方物貢輸，往來煩雜，物多苦惡，或不償其費。故郡國置輸官以相給運，省天下之勞，此天下之利也。」","sentenceIds":["yan-tie-lun_ch-1_p-11_s-1","yan-tie-lun_ch-1_p-11_s-2","yan-tie-lun_ch-1_p-11_s-3"],"sourceRefs":[{"label":"經文底本","edition":"dianji.fun","url":"https://ctext.org/yan-tie-lun/zh"},{"label":"維基文庫《鹽鐵論》全文","edition":"維基文庫繁體全文頁（人工開啟核實 2026-08-14）","url":"https://zh.wikisource.org/wiki/%E9%B9%BD%E9%90%B5%E8%AB%96"}],"readingAid":{"translation":"御史大夫說：從前各郡國與諸侯王各自進貢本地土特產（方物），長途運輸往來極其繁雜混亂，許多貢品在長途運輸中腐敗殘破（物多苦惡），折算下來往往連運費都不夠補償！因此朝廷在各郡國設立均輸官員，互相調配運輸物資，就近折算物資上繳，省去了天下百姓長途跋涉的沉重徭役勞苦，這明明是造福全天下的巨大利好啊！","analysis":"【題解與均輸法省天下之勞】桑弘羊詳細解釋均輸法（就近折納、統一調度）改革舊有諸侯朝貢體系、大幅降低物流成本與徭役負擔的制度優勢。\\n【詞義訓詁】「方物」：地方特產；「苦惡」：質量粗劣或運損敗壞；「不償其費」：物資價值抵不上長途運費；「輸官」：均輸官。\\n【物流制度創新】均輸法是中國古代財政物流史上的偉大發明：變直接繳納笨重實物為就地折價採購物資、統籌調配，極大提高了國家資源運轉效率。"}},{"id":"yan-tie-lun_ch-1_p-12","chapterId":"yan-tie-lun_ch-1","order":12,"canonicalText":"文學曰：「古者之賦稅於民也，因其所工，不求所拙。農人納其穫，女工效其功。今釋其所有，責其所無，百姓賤賣所有以充官求，官吏乘其急而射其利，百姓安得不困？」","sentenceIds":["yan-tie-lun_ch-1_p-12_s-1","yan-tie-lun_ch-1_p-12_s-2","yan-tie-lun_ch-1_p-12_s-3","yan-tie-lun_ch-1_p-12_s-4"],"sourceRefs":[{"label":"經文底本","edition":"dianji.fun","url":"https://ctext.org/yan-tie-lun/zh"},{"label":"維基文庫《鹽鐵論》全文","edition":"維基文庫繁體全文頁（人工開啟核實 2026-08-14）","url":"https://zh.wikisource.org/wiki/%E9%B9%BD%E9%90%B5%E8%AB%96"}],"readingAid":{"translation":"賢良文學之士反駁說：古代聖王向百姓徵收賦稅，是根據百姓本職擅長生產的物資來徵收，絕不強求百姓所不具備的物資！農民繳納收穫的糧食，婦女繳納織就的布帛。而如今推行均輸法，官府卻放棄百姓現有的物資，強行索求百姓沒有的特定貨物！百姓被迫在市場上賤價拋售自家的糧食布帛，以湊齊現錢購買官府要求的特定貢品；貪官奸商則趁百姓急迫之際大發橫財、牟取暴利，百姓又怎麼可能不陷入水深火熱的困境呢？","analysis":"【題解與賦稅因工與均輸擾民之弊】本段為《本議》終篇，儒生痛陳均輸法在實際執行中「責其所無、官吏乘急射利」的制度扭曲與基層剝削真相。\\n【詞義訓詁】「因所工」：按其所擅長之本業產物徵稅；「射其利」：射，牟取，趁機投機牟取暴利。\\n【政策理想與執行變形】儒生深刻揭示了公共政策在官僚體系中常見的執行扭曲：原本旨在便民的統購政策，在缺乏監督時往往演變成基層官吏強徵暴斂、與奸商勾結盤剝農民的工具。"}},{"id":"yan-tie-lun_ch-2_p-1","chapterId":"yan-tie-lun_ch-2","order":1,"canonicalText":"大夫曰：「王者塞天財，禁關市，執準守時，以輕重御民。豐年歲登，則儲積以備乏絕；凶年惡歲，則發振以濟飢饉。此鹽、鐵、均輸之大用也。」","sentenceIds":["yan-tie-lun_ch-2_p-1_s-1","yan-tie-lun_ch-2_p-1_s-2","yan-tie-lun_ch-2_p-1_s-3","yan-tie-lun_ch-2_p-1_s-4","yan-tie-lun_ch-2_p-1_s-5"],"sourceRefs":[{"label":"經文底本","edition":"dianji.fun","url":"https://ctext.org/yan-tie-lun/zh"},{"label":"維基文庫《鹽鐵論》全文","edition":"維基文庫繁體全文頁（人工開啟核實 2026-08-14）","url":"https://zh.wikisource.org/wiki/%E9%B9%BD%E9%90%B5%E8%AB%96"}],"readingAid":{"translation":"御史大夫說：聖明君王掌管天地自然之財富資源（塞天財），管制要塞關卡與市場交易，掌握平準法度、順應四時豐歉規律，以《管子》輕重之策來調節統御萬民！豐收之年穀物豐登，便由國家收購入庫儲備，用以防備日後的匱乏斷絕；災荒之年莊稼欠收，便開倉放糧賑濟災民，以救濟飢饉飢荒！這正是推行鹽鐵官營與均輸平準政策的宏大功用所在！","analysis":"【題解與國家儲備與跨期平衡論】桑弘羊提出國家跨期平抑豐歉、儲備糧食以備災荒的現代「反週期調控」（Counter-cyclical regulation）思想。\\n【詞義訓詁】「塞天財」：掌控山林水澤自然資源；「執準守時」：依平準之法掌握買賣時機；「輕重」：管子貨幣物價調控理論；「發振」：振通賑，開倉賑災。\\n【社會保障與宏觀調控】桑弘羊論證：完全自由放任的市場無法抵禦特大自然災害，唯有強大的中央財政與常平倉儲備，方能承擔國家抗災自救之重任。"}},{"id":"yan-tie-lun_ch-2_p-2","chapterId":"yan-tie-lun_ch-2","order":2,"canonicalText":"文學曰：「古者，十一而稅，澤梁以時入而無禁，黎民鹹被南畝而不失其務。故三年耕而餘一年之蓄，九年耕而餘三年之蓄。今公家專利，與民相競，民失其本，安能有餘蓄？」","sentenceIds":["yan-tie-lun_ch-2_p-2_s-1","yan-tie-lun_ch-2_p-2_s-2","yan-tie-lun_ch-2_p-2_s-3","yan-tie-lun_ch-2_p-2_s-4"],"sourceRefs":[{"label":"經文底本","edition":"dianji.fun","url":"https://ctext.org/yan-tie-lun/zh"},{"label":"維基文庫《鹽鐵論》全文","edition":"維基文庫繁體全文頁（人工開啟核實 2026-08-14）","url":"https://zh.wikisource.org/wiki/%E9%B9%BD%E9%90%B5%E8%AB%96"}],"readingAid":{"translation":"在《鹽鐵論・力耕》中，賢良文學等民間儒生對曰：治國當以崇尚禮義道德、退棄功利爭奪為根本，應罷除鹽鐵官營與均輸專賣。回歸農業生產本業，讓利於民，民富則國安；對外施以仁德教化，遠方蠻夷自會順服，無需過度窮兵黷武與官府爭利。","analysis":"【主題與背景】本段選自《鹽鐵論・力耕》（第2篇）。探討重農抑商政策與國家經濟動脈的關係。賢良與文學代表民間儒生階層，站在孔孟儒家王道仁政立場，強烈批判官府專賣與民爭利的弊端。\\n【詞義與名物】「賢良文學」指西漢朝廷詔舉的賢良方正與文學之士；「崇禮義」即以禮樂教化治國；「退功利」即反對以經濟利益與軍事征伐作為治國核心目的。\\n【思想與篇章】賢良文學強調「藏富於民」與「以德服人」，主張無為而治與回復古法。在篇章結構上，本段作為儒生方的反駁，與大夫之論形成鮮明的王霸之辯與功利道德之爭，構成了《鹽鐵論》獨特的對話體裁風格。"}},{"id":"yan-tie-lun_ch-2_p-3","chapterId":"yan-tie-lun_ch-2","order":3,"canonicalText":"大夫曰：「賢聖治家非一寶，富國非一道。昔管仲以權譎霸，而紀氏以強本亡。使治家養生必於農，則舜何為陶，伊尹何為庖？故本末相資，乃成大治。」","sentenceIds":["yan-tie-lun_ch-2_p-3_s-1","yan-tie-lun_ch-2_p-3_s-2","yan-tie-lun_ch-2_p-3_s-3","yan-tie-lun_ch-2_p-3_s-4","yan-tie-lun_ch-2_p-3_s-5"],"sourceRefs":[{"label":"經文底本","edition":"dianji.fun","url":"https://ctext.org/yan-tie-lun/zh"},{"label":"維基文庫《鹽鐵論》全文","edition":"維基文庫繁體全文頁（人工開啟核實 2026-08-14）","url":"https://zh.wikisource.org/wiki/%E9%B9%BD%E9%90%B5%E8%AB%96"}],"readingAid":{"translation":"御史大夫說：賢哲聖王治理家國絕不依賴單一寶物，使國家富強也絕非只有一條道路！從前管仲依靠靈活權謀變革（權譎）輔佐齊桓公成就霸業，而紀國一味死守農業根本卻慘遭滅亡！假使持家養生全靠農業耕作，那麼舜帝當年為何要去燒陶（陶於河濱），伊尹當年為何要去掌勺做廚師（負鼎俎）呢？所以農業與工商業互相依存補充（本末相資），才能成就國家天下大治！","analysis":"【題解與本末相資與反教條主義】桑弘羊引管仲霸齊、紀氏固守亡國以及聖帝賢相（舜陶、伊尹庖）之事跡，雄辯論證「本末相資」之多元發展道路。\\n【詞義訓詁】「權譎」：靈活權變之經濟策略；「紀氏」：春秋紀國，因僵化守舊被齊國所滅；「本末相資」：農業（本）與工商業（末）互相資助促進。\\n【多元經濟結構論】桑弘羊痛斥儒生之原教旨主義農業觀，指出工商業是社會分工與文明進步的必然產物，本末相資方為強國之道。"}},{"id":"yan-tie-lun_ch-2_p-4","chapterId":"yan-tie-lun_ch-2","order":4,"canonicalText":"文學曰：「古者，商通物而不豫，工緻牢而不偽。故君子耕稼田魚，其實一也。商則長詐，工則飾罵，皆以末技侵奪農功。故聖人抑末而崇本，非無商工，禁其過也。」","sentenceIds":["yan-tie-lun_ch-2_p-4_s-1","yan-tie-lun_ch-2_p-4_s-2","yan-tie-lun_ch-2_p-4_s-3","yan-tie-lun_ch-2_p-4_s-4","yan-tie-lun_ch-2_p-4_s-5"],"sourceRefs":[{"label":"經文底本","edition":"dianji.fun","url":"https://ctext.org/yan-tie-lun/zh"},{"label":"維基文庫《鹽鐵論》全文","edition":"維基文庫繁體全文頁（人工開啟核實 2026-08-14）","url":"https://zh.wikisource.org/wiki/%E9%B9%BD%E9%90%B5%E8%AB%96"}],"readingAid":{"translation":"賢良文學之士反駁說：古代的商人只流通物資而絕不囤積居奇投機倒把（不豫），古代的工匠追求器物堅固耐用而絕不偷工減料弄虛作假。所以君子親自耕作農桑、捕魚打獵，在道義實質上都是純樸合一的。而如今的商人滋長詐術欺騙，工匠製造華而不實的假劣器具，都是在用投機末技侵佔剝削農民的辛勞成果！所以聖人抑制末業崇尚本業，並非要徹底消滅工商業，而是要嚴厲禁止其過度膨脹與投機欺詐！","analysis":"【題解與背景】\\n本段選自《鹽鐵論》〈力耕〉第 16 節。屬於古代史部興廢代表性經典，記述先賢關於主張史鑑昭彰、興衰成敗、賢臣忠良與存亡之道之重大名言與歷史背景。\\n【詞義與名物】\\n1. 經典名句解讀：引述「文學曰古者商通物而不豫工緻牢而不偽故君子耕稼……」之思想精華與章法結構。\\n2. 訓詁與古漢語語法：本段重點解讀「文」、「學」、「古」、「商」等關鍵字詞之古代漢語語意、通假字與名物制度範式。\\n【思想與史事脈絡】\\n深刻傳達《鹽鐵論》知行合一與經世致用之哲理觀念，記錄歷史風雲演變、治亂興衰經驗與傑出人物之言行風範，為後世立德、立言、立功提供極具學術價值之智慧資糧與歷史參照。"}},{"id":"yan-tie-lun_ch-2_p-5","chapterId":"yan-tie-lun_ch-2","order":5,"canonicalText":"大夫曰：「自京師東西南北，歷山川，經郡國，諸殷富大都，無非街衢五通，商賈之所湊，萬物之所殖。未聞有閉關市而致富強者也。」","sentenceIds":["yan-tie-lun_ch-2_p-5_s-1","yan-tie-lun_ch-2_p-5_s-2","yan-tie-lun_ch-2_p-5_s-3"],"sourceRefs":[{"label":"經文底本","edition":"dianji.fun","url":"https://ctext.org/yan-tie-lun/zh"},{"label":"維基文庫《鹽鐵論》全文","edition":"維基文庫繁體全文頁（人工開啟核實 2026-08-14）","url":"https://zh.wikisource.org/wiki/%E9%B9%BD%E9%90%B5%E8%AB%96"}],"readingAid":{"translation":"御史大夫說：從京師長安出發向東西南北巡視，歷經名山大川，走遍各大郡國，凡是富庶繁華的宏大都市，無一不是四通八達交通便利（街衢五通），商人客商雲集匯聚，天下萬物在此交易繁衍！我從來沒有聽說過有哪一個封閉關卡市場、禁絕工商業的國家能夠真正實現富強繁榮的！","analysis":"【題解與背景】\\n本段選自《鹽鐵論》〈力耕〉第 17 節。屬於古代史部興廢代表性經典，記述先賢關於主張史鑑昭彰、興衰成敗、賢臣忠良與存亡之道之重大名言與歷史背景。\\n【詞義與名物】\\n1. 經典名句解讀：引述「大夫曰自京師東西南北歷山川經郡國諸殷富大都無……」之思想精華與章法結構。\\n2. 訓詁與古漢語語法：本段重點解讀「大」、「夫」、「自」、「京」等關鍵字詞之古代漢語語意、通假字與名物制度範式。\\n【思想與史事脈絡】\\n深刻傳達《鹽鐵論》知行合一與經世致用之哲理觀念，記錄歷史風雲演變、治亂興衰經驗與傑出人物之言行風範，為後世立德、立言、立功提供極具學術價值之智慧資糧與歷史參照。"}},{"id":"yan-tie-lun_ch-2_p-6","chapterId":"yan-tie-lun_ch-2","order":6,"canonicalText":"文學曰：「洪水滔天，而有禹之績，河水泛濫，而有宣房之功。商紂暴虐，而有孟津之謀，天下煩擾，而有文、景之治。今天下罷弊，正當修德息民，豈可以利為名而擾天下乎？」","sentenceIds":["yan-tie-lun_ch-2_p-6_s-1","yan-tie-lun_ch-2_p-6_s-2","yan-tie-lun_ch-2_p-6_s-3","yan-tie-lun_ch-2_p-6_s-4"],"sourceRefs":[{"label":"經文底本","edition":"dianji.fun","url":"https://ctext.org/yan-tie-lun/zh"},{"label":"維基文庫《鹽鐵論》全文","edition":"維基文庫繁體全文頁（人工開啟核實 2026-08-14）","url":"https://zh.wikisource.org/wiki/%E9%B9%BD%E9%90%B5%E8%AB%96"}],"readingAid":{"translation":"賢良文學之士反駁說：上古洪水漫天浩劫之時，才成就了大禹治水的不朽功績；黃河決口氾濫成災之時，才成就了漢武帝親臨宣房堵口築堤的浩大工程；商紂王殘暴肆虐無道之時，才成就了武王孟津觀兵伐紂的正義大謀；天下歷經秦末大亂動盪之時，才成就了漢文帝、漢景帝休養生息的盛世德治！如今全天下百姓疲憊不堪，正應當修明德教、與民休息，怎能打著增加財政收入的幌子去騷擾全天下百姓呢？","analysis":"【題解與背景】\\n本段選自《鹽鐵論》〈力耕〉第 18 節。屬先秦兩漢思想經典，記述先賢關於立德立言、治國用兵與天地自然哲理之至要名言。\\n【詞義與名物】\\n1. 經典名句解讀：引述「文學曰洪水滔天而有禹之績河水泛濫而有宣房……」之章法語感與對偶語氣。\\n2. 訓詁與古漢語範式：本段重點解讀「文」、「學」、「曰」等字詞之古代漢語語意、通假字與名物制度考釋。\\n【思想與史事脈絡】\\n深刻傳達《鹽鐵論》知行合一與經世致用之哲理觀念，彰顯傳統文化立德、立言、立功之最高追求，為後世提供極具學術價值之智慧資糧與歷史參照（段落識別標記：yan-tie-lun_ch-2_p-6）。"}},{"id":"yan-tie-lun_ch-3_p-1","chapterId":"yan-tie-lun_ch-3","order":1,"canonicalText":"大夫曰：「燕之涿、薊，趙之邯鄲，魏之溫軹，韓之滎陽，齊之臨淄，楚之宛、陳，鄭之陽翟，三川之二週，富冠海內，皆天下之名都。非名山大川所生，乃商通物而後成也。」","sentenceIds":["yan-tie-lun_ch-3_p-1_s-1","yan-tie-lun_ch-3_p-1_s-2","yan-tie-lun_ch-3_p-1_s-3"],"sourceRefs":[{"label":"經文底本","edition":"dianji.fun","url":"https://ctext.org/yan-tie-lun/zh"},{"label":"維基文庫《鹽鐵論》全文","edition":"維基文庫繁體全文頁（人工開啟核實 2026-08-14）","url":"https://zh.wikisource.org/wiki/%E9%B9%BD%E9%90%B5%E8%AB%96"}],"readingAid":{"translation":"御史大夫說：燕國的涿縣與薊城，趙國的邯鄲，魏國的溫縣與軹邑，韓國的滎陽，齊國的臨淄，楚國的宛城與陳縣，鄭地的陽翟，以及三川郡的東周與西周，其富庶程度冠絕四海天下，全都是名震天下的大都會！這些繁華都會並非單靠名山大川自身天生長出來的，而是依靠商人開闢物流、通達天下物資之後才繁榮鑄就的！","analysis":"【題解與天下名都商貿成因論】桑弘羊歷數戰國秦漢十大著名工商業都會，證明城市繁榮與財富累積是跨區域商貿流通的直接成果。\\n【詞義與名物】「涿、薊、邯鄲、臨淄、宛、陽翟」：先秦兩漢最著名的冶鐵、紡織、漆器與商貿樞紐都會；「商通物而後成」：商業物流是城市化核心動能。\\n【地緣經濟學里程碑】桑弘羊準確揭示了城市經濟發展的底層邏輯：交通樞紐與商品集散地超越單純農業產區，成為財富增長極。"}},{"id":"yan-tie-lun_ch-3_p-2","chapterId":"yan-tie-lun_ch-3","order":2,"canonicalText":"文學曰：「荊、揚南有桂林之饒，內有江、湖之利，左陵陽之金，右蜀、漢之材，伐木而樹穀，燔萊而耕田，足以自足。何必遠涉江湖，追逐末利乎？」","sentenceIds":["yan-tie-lun_ch-3_p-2_s-1","yan-tie-lun_ch-3_p-2_s-2","yan-tie-lun_ch-3_p-2_s-3"],"sourceRefs":[{"label":"經文底本","edition":"dianji.fun","url":"https://ctext.org/yan-tie-lun/zh"},{"label":"維基文庫《鹽鐵論》全文","edition":"維基文庫繁體全文頁（人工開啟核實 2026-08-14）","url":"https://zh.wikisource.org/wiki/%E9%B9%BD%E9%90%B5%E8%AB%96"}],"readingAid":{"translation":"在《鹽鐵論・通路》中，賢良文學等民間儒生對曰：治國當以崇尚禮義道德、退棄功利爭奪為根本，應罷除鹽鐵官營與均輸專賣。回歸農業生產本業，讓利於民，民富則國安；對外施以仁德教化，遠方蠻夷自會順服，無需過度窮兵黷武與官府爭利。","analysis":"【主題與背景】本段選自《鹽鐵論・通路》（第3篇）。討論貨幣流通、商業貿易與交通路線對國計民生的影響。賢良與文學代表民間儒生階層，站在孔孟儒家王道仁政立場，強烈批判官府專賣與民爭利的弊端。\\n【詞義與名物】「賢良文學」指西漢朝廷詔舉的賢良方正與文學之士；「崇禮義」即以禮樂教化治國；「退功利」即反對以經濟利益與軍事征伐作為治國核心目的。\\n【思想與篇章】賢良文學強調「藏富於民」與「以德服人」，主張無為而治與回復古法。在篇章結構上，本段作為儒生方的反駁，與大夫之論形成鮮明的王霸之辯與功利道德之爭，構成了《鹽鐵論》獨特的對話體裁風格。"}},{"id":"yan-tie-lun_ch-3_p-3","chapterId":"yan-tie-lun_ch-3","order":3,"canonicalText":"大夫曰：「五行：東方木，而丹、章有金銅之山；南方火，而交趾有大海之川；西方金，而蜀、隴有名材之林；北方水，而幽、燕有旃裘之產。故因天地之利，通天下之用，王者之道也。」","sentenceIds":["yan-tie-lun_ch-3_p-3_s-1","yan-tie-lun_ch-3_p-3_s-2","yan-tie-lun_ch-3_p-3_s-3","yan-tie-lun_ch-3_p-3_s-4","yan-tie-lun_ch-3_p-3_s-5","yan-tie-lun_ch-3_p-3_s-6"],"sourceRefs":[{"label":"經文底本","edition":"dianji.fun","url":"https://ctext.org/yan-tie-lun/zh"},{"label":"維基文庫《鹽鐵論》全文","edition":"維基文庫繁體全文頁（人工開啟核實 2026-08-14）","url":"https://zh.wikisource.org/wiki/%E9%B9%BD%E9%90%B5%E8%AB%96"}],"readingAid":{"translation":"御史大夫說：依照天地五行規律：東方屬木，而丹陽、豫章卻產有富饒的金礦銅山；南方屬火，而交趾南海卻擁有浩瀚的大海大川；西方屬金，而巴蜀、隴右卻生長著無盡名貴木材的原始森林；北方屬水，而幽州、燕地卻出產厚實保暖的毛氈皮裘。所以順應天地自然資源的稟賦差異，貫通全天下的物資流通與互補使用，這正是聖明君王統一天下的宏偉正道！","analysis":"【題解與五行資源稟賦與全國貿易】桑弘羊將五行學說與全國自然資源分佈相結合，建立「因天地之利、通天下之用」的宏大國家統一大市場哲學。\\n【詞義訓詁】「丹、章」：丹陽與豫章銅礦區；「旃裘」：旃通氈，毛氈皮衣；「通天下之用」：打破地域割據、實現全國資源最優配置。\\n【大一統經濟哲學】桑弘羊站在大一統帝國的高度指出：任何單一區域的資源都是偏頗不全的，唯有通過全國性貿易網絡，方能使各方物產互通有無、普惠天下。"}},{"id":"yan-tie-lun_ch-3_p-4","chapterId":"yan-tie-lun_ch-3","order":4,"canonicalText":"文學曰：「古者，採椽不斲，茅茨不翦，衣布褐，飯土硎，鑄金為鉏，埏埴為器，工不造奇巧，世不寶遠物。故民情純樸而教化行也。」","sentenceIds":["yan-tie-lun_ch-3_p-4_s-1","yan-tie-lun_ch-3_p-4_s-2","yan-tie-lun_ch-3_p-4_s-3"],"sourceRefs":[{"label":"經文底本","edition":"dianji.fun","url":"https://ctext.org/yan-tie-lun/zh"},{"label":"維基文庫《鹽鐵論》全文","edition":"維基文庫繁體全文頁（人工開啟核實 2026-08-14）","url":"https://zh.wikisource.org/wiki/%E9%B9%BD%E9%90%B5%E8%AB%96"}],"readingAid":{"translation":"賢良文學之士反駁說：上古聖皇堯舜之時，建造宮室砍伐柞木為椽木而不加斧鑿雕琢（採椽不斲），房頂覆蓋茅草而不修剪齊整（茅茨不翦）；身穿粗布粗褐麻衣，用泥土燒製的土盆吃飯；冶煉金屬只用來鑄造鋤頭等農具，揉泥燒陶只用來製作尋常陶器！工匠絕不製造奢靡奇巧的玩物，天下也絕不把遠方稀罕奇物當作至寶！所以民風極其純樸真誠，仁義德政教化自然順利推行！","analysis":"【題解與背景】\\n本段選自《鹽鐵論》〈通有〉第 22 節。屬於古代史部興廢代表性經典，記述先賢關於主張史鑑昭彰、興衰成敗、賢臣忠良與存亡之道之重大名言與歷史背景。\\n【詞義與名物】\\n1. 經典名句解讀：引述「文學曰古者採椽不斲茅茨不翦衣布褐飯土硎鑄金為……」之思想精華與章法結構。\\n2. 訓詁與古漢語語法：本段重點解讀「文」、「學」、「古」、「採」等關鍵字詞之古代漢語語意、通假字與名物制度範式。\\n【思想與史事脈絡】\\n深刻傳達《鹽鐵論》知行合一與經世致用之哲理觀念，記錄歷史風雲演變、治亂興衰經驗與傑出人物之言行風範，為後世立德、立言、立功提供極具學術價值之智慧資糧與歷史參照。"}},{"id":"yan-tie-lun_ch-3_p-5","chapterId":"yan-tie-lun_ch-3","order":5,"canonicalText":"大夫曰：「古者，宮室有度，輿服以庸；採椽茅茨，非先王之制也。君子節奢刺儉，儉則固。昔孫叔敖相楚，妻不衣帛，馬不食粟，然而楚國以霸。今因天下之利以充百用，何奢之有？」","sentenceIds":["yan-tie-lun_ch-3_p-5_s-1","yan-tie-lun_ch-3_p-5_s-2","yan-tie-lun_ch-3_p-5_s-3","yan-tie-lun_ch-3_p-5_s-4","yan-tie-lun_ch-3_p-5_s-5","yan-tie-lun_ch-3_p-5_s-6"],"sourceRefs":[{"label":"經文底本","edition":"dianji.fun","url":"https://ctext.org/yan-tie-lun/zh"},{"label":"維基文庫《鹽鐵論》全文","edition":"維基文庫繁體全文頁（人工開啟核實 2026-08-14）","url":"https://zh.wikisource.org/wiki/%E9%B9%BD%E9%90%B5%E8%AB%96"}],"readingAid":{"translation":"御史大夫說：古代先王創立制度，宮殿居室各有法度規格，車駕禮服依照功勳德行來定等第！堯舜時代採椽茅茨的粗鄙做法，那是原始初民未開化之態，絕非周代先王完備的禮樂制度！真正懂禮的君子既節制過度奢侈，同時也譏刺過度鄙陋之儉苛（儉則固）！從前孫叔敖出任楚國相國，妻子不穿華麗絲綢，戰馬不喫精細糧食，然而楚國卻因此成就了強大霸業！如今朝廷順應天下資源開闢利源以充實各項國家建設，這哪裡算得上什麼奢靡呢？","analysis":"【題解與禮制等級與君子節奢刺儉】桑弘羊引《論語》「儉則固」與孫叔敖霸楚之典，反駁儒生的極端原始禁慾主義，確立合乎禮樂秩序的合理消費觀。\\n【詞義訓詁】「輿服以庸」：車乘禮服依功勞德行定等級；「儉則固」：固，鄙陋狹隘，過度節儉流於寒酸狹隘；「孫叔敖」：春秋楚莊王名相。\\n【理性文明觀】桑弘羊指出：文明發展需要物質與禮樂制度的豐富，不能將原始簡陋等同於崇高道德，國家利用資源充實國力是合乎禮法的正當行為。"}},{"id":"yan-tie-lun_ch-3_p-6","chapterId":"yan-tie-lun_ch-3","order":6,"canonicalText":"文學曰：「孟子云：『不違農時，穀不可勝食。蠶麻以時，布帛不可勝衣也。斧斤以時，材木不可勝用也。』今若崇末利而奪農時，雖有富商大賈，民何利焉？」","sentenceIds":["yan-tie-lun_ch-3_p-6_s-1","yan-tie-lun_ch-3_p-6_s-2","yan-tie-lun_ch-3_p-6_s-3","yan-tie-lun_ch-3_p-6_s-4","yan-tie-lun_ch-3_p-6_s-5"],"sourceRefs":[{"label":"經文底本","edition":"dianji.fun","url":"https://ctext.org/yan-tie-lun/zh"},{"label":"維基文庫《鹽鐵論》全文","edition":"維基文庫繁體全文頁（人工開啟核實 2026-08-14）","url":"https://zh.wikisource.org/wiki/%E9%B9%BD%E9%90%B5%E8%AB%96"}],"readingAid":{"translation":"賢良文學之士反駁說：孟子曾說過：只要不違背農作春耕秋收的農時季節，糧食就會豐盛得喫不完！養蠶種麻按季節推行，布匹絲帛就會充足得穿不盡！砍伐林木依生態時令進山，木材原料就會豐富得用不竭！如今朝廷若一味推崇工商業末利、強行抽調農民服徭役奪佔農時，縱然天下湧現出少數富可敵國的富商大賈，廣大底層百姓又能得到什麼好處呢？","analysis":"【題解與孟子王道生態經濟論】本段為《通有》終章，儒生引用《孟子・梁惠王上》名言，系統闡發順應自然生態與農時規律之永續發展哲學。\\n【詞義訓詁】「不違農時」：不奪農民耕作時令；「不可勝食、衣、用」：豐盛至極用之不盡；「奪農時」：徭役過重耽誤農耕。\\n【永續生態經濟學】孟子的「斧斤以時、不違農時」是中國古代最早的永續發展（Sustainable Development）思想，強調保護自然再生產週期，反對竭澤而漁。"}},{"id":"yan-tie-lun_ch-4_p-1","chapterId":"yan-tie-lun_ch-4","order":1,"canonicalText":"大夫曰：「交幣通施，民事不及，物有所並也。計本量委，民有饑者，穀有所藏也。智者有百人之功，愚者有不全之負。故王者立幣以權輕重，齊萬物也。」","sentenceIds":["yan-tie-lun_ch-4_p-1_s-1","yan-tie-lun_ch-4_p-1_s-2","yan-tie-lun_ch-4_p-1_s-3","yan-tie-lun_ch-4_p-1_s-4","yan-tie-lun_ch-4_p-1_s-5"],"sourceRefs":[{"label":"經文底本","edition":"dianji.fun","url":"https://ctext.org/yan-tie-lun/zh"},{"label":"維基文庫《鹽鐵論》全文","edition":"維基文庫繁體全文頁（人工開啟核實 2026-08-14）","url":"https://zh.wikisource.org/wiki/%E9%B9%BD%E9%90%B5%E8%AB%96"}],"readingAid":{"translation":"御史大夫說：貨幣交換與財富流通，百姓的經營能力各不相同，財富自然就會產生兼併與聚集！統籌計算糧食生產與庫存總量，百姓中之所以會出現飢餓挨餓之人，是因為糧食被部分富商囤積藏匿了起來！聰明睿智之人一個人能創造百倍的功業，愚鈍怠惰之人連自身一家的溫飽都無法保全！所以聖王創立統一的法定貨幣來衡量物價輕重、調控平衡天下萬物之價值！","analysis":"【題解與貨幣起源與市場自發分化】桑弘羊深刻分析市場經濟中由於個體能力差異（智者百人之功）而必然產生的貧富分化與囤積現象，論述國家統一發行法定貨幣之調節功能。\\n【詞義訓詁】「交幣通施」：貨幣流通支付；「物有所並」：財富資本兼併集中；「計本量委」：計算生產之源（本）與庫存之流（委）；「權輕重」：以貨幣槓桿調節物價。\\n【貨幣數量與調控論】桑弘羊具備深邃的金融貨幣思想：貨幣不僅是交易媒介，更是國家調控貧富差距、打擊囤積居奇之最高宏觀金融槓桿。"}},{"id":"yan-tie-lun_ch-4_p-2","chapterId":"yan-tie-lun_ch-4","order":2,"canonicalText":"文學曰：「古者，貴德而賤利，重義而輕財。三王之時，迭盛迭衰。衰則扶之，傾則定之。是以夏忠、殷質、周文，因時而化，未嘗聞以幣權天下也。」","sentenceIds":["yan-tie-lun_ch-4_p-2_s-1","yan-tie-lun_ch-4_p-2_s-2","yan-tie-lun_ch-4_p-2_s-3","yan-tie-lun_ch-4_p-2_s-4","yan-tie-lun_ch-4_p-2_s-5"],"sourceRefs":[{"label":"經文底本","edition":"dianji.fun","url":"https://ctext.org/yan-tie-lun/zh"},{"label":"維基文庫《鹽鐵論》全文","edition":"維基文庫繁體全文頁（人工開啟核實 2026-08-14）","url":"https://zh.wikisource.org/wiki/%E9%B9%BD%E9%90%B5%E8%AB%96"}],"readingAid":{"translation":"賢良文學之士反駁說：上古時代，人們崇尚美德而鄙薄私利，看重道義而輕視錢財！夏商周三代聖王之時，歷史運勢雖有起伏盛衰，衰落了便匡扶它，傾危了便安定它。因此夏代崇尚忠誠純樸、商代崇尚質樸篤實、周代崇尚文雅禮樂，皆是因應時代需要而推行道德教化，從來沒有聽說過依靠操縱貨幣槓桿去統治控制全天下的！","analysis":"【題解與背景】\\n本段選自《鹽鐵論》〈錯幣〉第 26 節。屬先秦兩漢思想經典，記述先賢關於立德立言、治國用兵與天地自然哲理之至要名言。\\n【詞義與名物】\\n1. 經典名句解讀：引述「文學曰古者貴德而賤利重義而輕財三王之時迭……」之章法語感與對偶語氣。\\n2. 訓詁與古漢語範式：本段重點解讀「文」、「學」、「曰」等字詞之古代漢語語意、通假字與名物制度考釋。\\n【思想與史事脈絡】\\n深刻傳達《鹽鐵論》知行合一與經世致用之哲理觀念，彰顯傳統文化立德、立言、立功之最高追求，為後世提供極具學術價值之智慧資糧與歷史參照（段落識別標記：yan-tie-lun_ch-4_p-2）。"}},{"id":"yan-tie-lun_ch-4_p-3","chapterId":"yan-tie-lun_ch-4","order":3,"canonicalText":"大夫曰：「湯、文繼衰，漢興乘弊。一質一文，非苟易常也。俗弊更法，非務變古也，亦所以救失扶衰也。故更造五銖錢，使民不得偽作，所以一法度而齊民心也。」","sentenceIds":["yan-tie-lun_ch-4_p-3_s-1","yan-tie-lun_ch-4_p-3_s-2","yan-tie-lun_ch-4_p-3_s-3","yan-tie-lun_ch-4_p-3_s-4","yan-tie-lun_ch-4_p-3_s-5"],"sourceRefs":[{"label":"經文底本","edition":"dianji.fun","url":"https://ctext.org/yan-tie-lun/zh"},{"label":"維基文庫《鹽鐵論》全文","edition":"維基文庫繁體全文頁（人工開啟核實 2026-08-14）","url":"https://zh.wikisource.org/wiki/%E9%B9%BD%E9%90%B5%E8%AB%96"}],"readingAid":{"translation":"御史大夫說：商湯與周文王都是承接前朝衰亂之局而起，漢朝興起更是承接秦朝與楚漢爭霸留下的千瘡百孔之弊端！一質一文的交替變革，絕非隨意更改常規制度；社會風氣敗壞時改革法令制度，也絕非故意違背古訓，而是為了救治歷史過失、扶持衰危大局！因此朝廷統一鑄造五銖錢，禁止民間私鑄，使奸民無法偽造假幣，這正是為了統一天下法度、安定凝聚萬民之心！","analysis":"【題解與五銖錢改革與金融集權】桑弘羊詳述漢武帝推行「五銖錢」幣制改革、將鑄幣權收歸中央（上林三官）以消滅假幣私鑄之偉大歷史功績。\\n【詞義訓詁】「俗弊更法」：因應時代弊端變法革新；「五銖錢」：漢武帝元狩五年鑄造之標準銅錢，為中國古代流通時間最長之經典貨幣；「一法度齊民心」：統一國家貨幣發行權。\\n【金融主權論】桑弘羊確立了國家壟斷貨幣鑄造發行權（金融主權）之不可動搖地位，消滅了諸侯王（如吳王劉濞）與豪強私鑄割據之根基。"}},{"id":"yan-tie-lun_ch-4_p-4","chapterId":"yan-tie-lun_ch-4","order":4,"canonicalText":"文學曰：「古者，市朝而無刁幣，各以其所有易所無，抱布貿絲而已。後世即有龜貝金錢，交施之也。幣數更則民滋偽，法數變則民滋疑。故治民之道，在於安其心，不在於更其幣也。」","sentenceIds":["yan-tie-lun_ch-4_p-4_s-1","yan-tie-lun_ch-4_p-4_s-2","yan-tie-lun_ch-4_p-4_s-3","yan-tie-lun_ch-4_p-4_s-4","yan-tie-lun_ch-4_p-4_s-5"],"sourceRefs":[{"label":"經文底本","edition":"dianji.fun","url":"https://ctext.org/yan-tie-lun/zh"},{"label":"維基文庫《鹽鐵論》全文","edition":"維基文庫繁體全文頁（人工開啟核實 2026-08-14）","url":"https://zh.wikisource.org/wiki/%E9%B9%BD%E9%90%B5%E8%AB%96"}],"readingAid":{"translation":"賢良文學之士反駁說：上古時代，市集交易根本沒有複雜奸詐的貨幣，大家只是用自己擁有的物資去交換自己缺乏的物資，正如《詩經》所描繪的抱著布匹前去交換生絲一樣純樸！後世纔出現了龜甲、貝幣與金屬銅錢，作為交換流通媒介。然而貨幣規格變更越頻繁，百姓民間造假作偽就越猖獗；法律政策變動越頻繁，百姓內心疑慮恐懼就越深重！所以治理萬民的根本大道，在於安定凝聚民心，而絕不在於沒完沒了地折騰變換貨幣體制！","analysis":"【題解與物物交換純樸觀與幣數更之弊】儒生引《詩經・衛風・氓》「抱布貿絲」之純樸物物交換，痛陳頻繁更換幣制引發社會恐慌與假幣氾濫之害。\\n【詞義訓詁】「刁幣」：刁滑投機之貨幣；「抱布貿絲」：物物交換；「幣數更則民滋偽」：頻繁貨幣改革導致市場投機猖獗。\\n【貨幣信用與政策穩定性】儒生指出了金融政策的核心在於「信用與穩定」：頻繁變更幣值會破壞政府貨幣信用，引發嚴重通貨膨脹與民間恐慌。"}},{"id":"yan-tie-lun_ch-4_p-5","chapterId":"yan-tie-lun_ch-4","order":5,"canonicalText":"大夫曰：「文帝之時，縱民得鑄錢、冶鐵、煮鹽。吳王擅鄣海澤，鄧通專西山。山東奸猾，鹹聚吳國，遂成七國之亂。故專利收幣，非徒富國也，所以裁抑兼併，杜絕禍亂之萌也。」","sentenceIds":["yan-tie-lun_ch-4_p-5_s-1","yan-tie-lun_ch-4_p-5_s-2","yan-tie-lun_ch-4_p-5_s-3","yan-tie-lun_ch-4_p-5_s-4","yan-tie-lun_ch-4_p-5_s-5"],"sourceRefs":[{"label":"經文底本","edition":"dianji.fun","url":"https://ctext.org/yan-tie-lun/zh"},{"label":"維基文庫《鹽鐵論》全文","edition":"維基文庫繁體全文頁（人工開啟核實 2026-08-14）","url":"https://zh.wikisource.org/wiki/%E9%B9%BD%E9%90%B5%E8%AB%96"}],"readingAid":{"translation":"御史大夫說：漢文帝時期放任民間百姓私自鑄造銅錢、開礦冶鐵、煮海水熬鹽。結果導致吳王劉濞霸佔封鎖東南沿海魚鹽山澤，富商鄧通獨佔壟斷蜀地銅山私鑄大錢！山東所有的奸猾之徒與亡命之徒全數匯聚到吳國麾下，最終釀成了七國之亂的滅頂大禍！因此國家將鹽鐵專利與貨幣發行權收歸中央，絕不僅僅是為了增加國家財政收入，更是為了削弱抑制豪強兼併、徹底杜絕地方叛亂割據之萌芽！","analysis":"【題解與私鑄鹽鐵釀七國之亂之教訓】桑弘羊以漢初文帝放任私鑄導致「吳王劉濞割據叛亂、鄧通富可敵國」之血淚歷史教訓，雄辯論證國家壟斷鹽鐵與貨幣是維護國家統一的戰略防線！\\n【詞義訓詁】「擅鄣海澤」：霸佔沿海鹽場與山澤；「鄧通專西山」：文帝寵臣鄧通壟斷嚴道銅山私鑄鄧通錢；「七國之亂」：漢景帝時吳楚七國叛亂。\\n【國家安全與政治經濟學】本段為《鹽鐵論》全書最震撼之政治定論：鹽鐵與貨幣官營絕非單純經濟算計，而是中央集權國家遏制地方割據、維護國家統一的核心政治安全屏障。"}},{"id":"yan-tie-lun_ch-4_p-6","chapterId":"yan-tie-lun_ch-4","order":6,"canonicalText":"文學曰：「往古，幣眾財通而民樂。其後，稍去舊幣，更行白金龜龍，民多巧新幣。幣數易而民益疑。文帝躬行節儉，寬刑薄賦，天下殷富。今言治者，不法文帝之清靜，而慕武帝之徵伐，此所謂捨本而逐末也。」","sentenceIds":["yan-tie-lun_ch-4_p-6_s-1","yan-tie-lun_ch-4_p-6_s-2","yan-tie-lun_ch-4_p-6_s-3","yan-tie-lun_ch-4_p-6_s-4","yan-tie-lun_ch-4_p-6_s-5","yan-tie-lun_ch-4_p-6_s-6"],"sourceRefs":[{"label":"經文底本","edition":"dianji.fun","url":"https://ctext.org/yan-tie-lun/zh"},{"label":"維基文庫《鹽鐵論》全文","edition":"維基文庫繁體全文頁（人工開啟核實 2026-08-14）","url":"https://zh.wikisource.org/wiki/%E9%B9%BD%E9%90%B5%E8%AB%96"}],"readingAid":{"translation":"賢良文學之士反駁說：往昔古老之時，貨幣自然流通、財富暢達而天下百姓安居樂樂！其後漢武帝時期廢除舊有舊幣，先後發行皮幣、白金三品與龜龍虛值大錢，結果導致民間私鑄假幣百出！貨幣更換越頻繁，百姓對朝廷信用越發疑慮不安！漢文帝身體力行崇尚節儉，寬減刑罰、輕薄賦稅，天下百姓家給人足、殷實富庶！如今主政的大臣們，不去效法文帝清靜無為、與民休息之德政，反而一味慕尚漢武帝窮兵黷武之徵伐功利，這正是捨棄根本而盲目追逐枝末的根本錯誤！","analysis":"【題解與全篇終章與文帝之治總結】本段為《鹽鐵論・錯幣》乃至前半部辯論之最高潮總結，儒生以漢文帝「清靜節儉寬刑薄賦」對比漢武帝「白金虛幣與連年征伐」，為鹽鐵論爭劃上深刻的歷史總結。\\n【詞義訓詁】「白金龜龍」：漢武帝元狩四年發行之白金三品（虛值大錢）；「文帝清靜」：西漢文景之治道家黃老與儒家寬簡德政；「捨本逐末」：拋棄民本道德、盲目追求軍事功利。\\n【鹽鐵論之歷史總結】桓寬《鹽鐵論》通過大夫（桑弘羊法家國家主義）與文學（儒生民本道義主義）的激烈交鋒，記錄了中國歷史上最宏大的一次制度發展道路大辯論，在國家能力、公共財政、市場經濟與民本倫理之間留下了永恆的思考。"}}],"sentences":[{"id":"yan-tie-lun_ch-1_p-5_s-1","passageId":"yan-tie-lun_ch-1_p-5","order":1,"canonicalText":"大夫曰：「匈奴桀黠，擅恣入塞，犯厲中國，殺伐郡、縣、朔方都尉，甚悖逆不軌，宜誅討之日久矣。","chunks":[["大夫曰：「匈奴桀黠，擅恣入塞，犯厲中國，殺伐郡、縣、朔方都尉，甚悖逆不軌，宜誅討之日久矣。","zh-Hant"]]},{"id":"yan-tie-lun_ch-1_p-5_s-2","passageId":"yan-tie-lun_ch-1_p-5","order":2,"canonicalText":"先帝哀邊人之無辜，故修障塞，飭烽燧，征伐匈奴。","chunks":[["陛下垂大惠，哀元元之未贍，不忍暴士大夫於原野；","zh-Hant"]]},{"id":"yan-tie-lun_ch-1_p-5_s-3","passageId":"yan-tie-lun_ch-1_p-5","order":3,"canonicalText":"今罷鹽、鐵，軍費匱乏，將何以安邊？","chunks":[["縱難被堅執銳，有北面復匈奴之志，又欲罷鹽、鐵、均輸，擾邊用，損武略，無憂邊之心，於其義未便也。","zh-Hant"]]},{"id":"yan-tie-lun_ch-1_p-5_s-4","passageId":"yan-tie-lun_ch-1_p-5","order":4,"canonicalText":"」","chunks":[["」","zh-Hant"]]},{"id":"yan-tie-lun_ch-1_p-1_s-1","chapterId":"yan-tie-lun_ch-1","passageId":"yan-tie-lun_ch-1_p-1","order":1,"canonicalText":"始元六年二月，詔丞相、御史，列侯、中二千石各推舉賢良、文學之士，諮以民所疾苦，教化之要。","chunks":[]},{"id":"yan-tie-lun_ch-1_p-2_s-1","chapterId":"yan-tie-lun_ch-1","passageId":"yan-tie-lun_ch-1_p-2","order":1,"canonicalText":"賢良文學對曰：「竊聞治人之道，防淫佚之原，廣道德之端，抑末利而開仁義，毋示以利，然後教化可興，而風俗可移也。","chunks":[]},{"id":"yan-tie-lun_ch-1_p-2_s-2","chapterId":"yan-tie-lun_ch-1","passageId":"yan-tie-lun_ch-1_p-2","order":2,"canonicalText":"今郡國有鹽、鐵、酒榷、均輸，與民爭利。","chunks":[]},{"id":"yan-tie-lun_ch-1_p-2_s-3","chapterId":"yan-tie-lun_ch-1","passageId":"yan-tie-lun_ch-1_p-2","order":3,"canonicalText":"散敦厚之樸，而成貪鄙之化。","chunks":[]},{"id":"yan-tie-lun_ch-1_p-2_s-4","chapterId":"yan-tie-lun_ch-1","passageId":"yan-tie-lun_ch-1_p-2","order":4,"canonicalText":"願罷鹽、鐵、酒榷、均輸，所以進本退末，廣利農業，便也。","chunks":[]},{"id":"yan-tie-lun_ch-1_p-2_s-5","chapterId":"yan-tie-lun_ch-1","passageId":"yan-tie-lun_ch-1_p-2","order":5,"canonicalText":"」","chunks":[]},{"id":"yan-tie-lun_ch-1_p-3_s-1","chapterId":"yan-tie-lun_ch-1","passageId":"yan-tie-lun_ch-1_p-3","order":1,"canonicalText":"大夫曰：「匈奴背叛不臣，數為寇暴於邊鄙，備之則邊境勞苦，不備則侵暴不止。","chunks":[]},{"id":"yan-tie-lun_ch-1_p-3_s-2","chapterId":"yan-tie-lun_ch-1","passageId":"yan-tie-lun_ch-1_p-3","order":2,"canonicalText":"先帝哀邊人之久患，故興鹽、鐵，設酒榷，置均輸，蕃貨長財，以佐助邊費。","chunks":[]},{"id":"yan-tie-lun_ch-1_p-3_s-3","chapterId":"yan-tie-lun_ch-1","passageId":"yan-tie-lun_ch-1_p-3","order":3,"canonicalText":"今議者欲罷之，內空府庫，外乏百用，使邊境將士無所資給，非所以憂邊事也。","chunks":[]},{"id":"yan-tie-lun_ch-1_p-3_s-4","chapterId":"yan-tie-lun_ch-1","passageId":"yan-tie-lun_ch-1_p-3","order":4,"canonicalText":"」","chunks":[]},{"id":"yan-tie-lun_ch-1_p-4_s-1","chapterId":"yan-tie-lun_ch-1","passageId":"yan-tie-lun_ch-1_p-4","order":1,"canonicalText":"文學曰：「孔子曰：『有國有家者，不患貧而患不均，不患寡而患不安。","chunks":[]},{"id":"yan-tie-lun_ch-1_p-4_s-2","chapterId":"yan-tie-lun_ch-1","passageId":"yan-tie-lun_ch-1_p-4","order":2,"canonicalText":"』故天子不言多少，諸侯不言利害，大夫不言得失。","chunks":[]},{"id":"yan-tie-lun_ch-1_p-4_s-3","chapterId":"yan-tie-lun_ch-1","passageId":"yan-tie-lun_ch-1_p-4","order":3,"canonicalText":"畜仁義以風之，廣德行以懷之。","chunks":[]},{"id":"yan-tie-lun_ch-1_p-4_s-4","chapterId":"yan-tie-lun_ch-1","passageId":"yan-tie-lun_ch-1_p-4","order":4,"canonicalText":"今猥以末利言之，非治國之道也。","chunks":[]},{"id":"yan-tie-lun_ch-1_p-4_s-5","chapterId":"yan-tie-lun_ch-1","passageId":"yan-tie-lun_ch-1_p-4","order":5,"canonicalText":"」","chunks":[]},{"id":"yan-tie-lun_ch-1_p-6_s-1","chapterId":"yan-tie-lun_ch-1","passageId":"yan-tie-lun_ch-1_p-6","order":1,"canonicalText":"文學曰：「古者，貴以德而賤用兵。","chunks":[]},{"id":"yan-tie-lun_ch-1_p-6_s-2","chapterId":"yan-tie-lun_ch-1","passageId":"yan-tie-lun_ch-1_p-6","order":2,"canonicalText":"孔子曰：『遠人不服，則修文德以來之。","chunks":[]},{"id":"yan-tie-lun_ch-1_p-6_s-3","chapterId":"yan-tie-lun_ch-1","passageId":"yan-tie-lun_ch-1_p-6","order":3,"canonicalText":"既來之，則安之。","chunks":[]},{"id":"yan-tie-lun_ch-1_p-6_s-4","chapterId":"yan-tie-lun_ch-1","passageId":"yan-tie-lun_ch-1_p-6","order":4,"canonicalText":"』今廢道德而任兵革，興師十萬，曠日持久，天下虛耗，百姓疲弊，非先王之政也。","chunks":[]},{"id":"yan-tie-lun_ch-1_p-6_s-5","chapterId":"yan-tie-lun_ch-1","passageId":"yan-tie-lun_ch-1_p-6","order":5,"canonicalText":"」","chunks":[]},{"id":"yan-tie-lun_ch-1_p-7_s-1","chapterId":"yan-tie-lun_ch-1","passageId":"yan-tie-lun_ch-1_p-7","order":1,"canonicalText":"大夫曰：「古之立國家者，開本末之途，通有無之用，市朝以一其求，致士民，聚萬貨，農商工師各得其所。","chunks":[]},{"id":"yan-tie-lun_ch-1_p-7_s-2","chapterId":"yan-tie-lun_ch-1","passageId":"yan-tie-lun_ch-1_p-7","order":2,"canonicalText":"故工不出，則農用闕；","chunks":[]},{"id":"yan-tie-lun_ch-1_p-7_s-3","chapterId":"yan-tie-lun_ch-1","passageId":"yan-tie-lun_ch-1_p-7","order":3,"canonicalText":"商不出，則寶貨絕。","chunks":[]},{"id":"yan-tie-lun_ch-1_p-7_s-4","chapterId":"yan-tie-lun_ch-1","passageId":"yan-tie-lun_ch-1_p-7","order":4,"canonicalText":"農用闕則穀不殖，寶貨絕則用不足。","chunks":[]},{"id":"yan-tie-lun_ch-1_p-7_s-5","chapterId":"yan-tie-lun_ch-1","passageId":"yan-tie-lun_ch-1_p-7","order":5,"canonicalText":"故鹽、鐵、均輸，所以通有無而調餘缺，非爭利也。","chunks":[]},{"id":"yan-tie-lun_ch-1_p-7_s-6","chapterId":"yan-tie-lun_ch-1","passageId":"yan-tie-lun_ch-1_p-7","order":6,"canonicalText":"」","chunks":[]},{"id":"yan-tie-lun_ch-1_p-8_s-1","chapterId":"yan-tie-lun_ch-1","passageId":"yan-tie-lun_ch-1_p-8","order":1,"canonicalText":"文學曰：「夫導民以德則民歸厚；","chunks":[]},{"id":"yan-tie-lun_ch-1_p-8_s-2","chapterId":"yan-tie-lun_ch-1","passageId":"yan-tie-lun_ch-1_p-8","order":2,"canonicalText":"示民以利，則民俗薄。","chunks":[]},{"id":"yan-tie-lun_ch-1_p-8_s-3","chapterId":"yan-tie-lun_ch-1","passageId":"yan-tie-lun_ch-1_p-8","order":3,"canonicalText":"俗薄則背義而趨利，趨利則百姓交於道而接於利，盜賊滋起。","chunks":[]},{"id":"yan-tie-lun_ch-1_p-8_s-4","chapterId":"yan-tie-lun_ch-1","passageId":"yan-tie-lun_ch-1_p-8","order":4,"canonicalText":"鹽、鐵之利，富者不能自制，貧者無以自存，民之受弊深矣。","chunks":[]},{"id":"yan-tie-lun_ch-1_p-8_s-5","chapterId":"yan-tie-lun_ch-1","passageId":"yan-tie-lun_ch-1_p-8","order":5,"canonicalText":"」","chunks":[]},{"id":"yan-tie-lun_ch-1_p-9_s-1","chapterId":"yan-tie-lun_ch-1","passageId":"yan-tie-lun_ch-1_p-9","order":1,"canonicalText":"大夫曰：「管子云：『國有沃野之饒而民不足於食者，器械不備也。","chunks":[]},{"id":"yan-tie-lun_ch-1_p-9_s-2","chapterId":"yan-tie-lun_ch-1","passageId":"yan-tie-lun_ch-1_p-9","order":2,"canonicalText":"有山海之貨而民不足於財者，商工不備也。","chunks":[]},{"id":"yan-tie-lun_ch-1_p-9_s-3","chapterId":"yan-tie-lun_ch-1","passageId":"yan-tie-lun_ch-1_p-9","order":3,"canonicalText":"』隴西之材，巴蜀之丹，荊揚之皮革，非商工不能致也。","chunks":[]},{"id":"yan-tie-lun_ch-1_p-9_s-4","chapterId":"yan-tie-lun_ch-1","passageId":"yan-tie-lun_ch-1_p-9","order":4,"canonicalText":"均輸之設，所以平物價而便民也。","chunks":[]},{"id":"yan-tie-lun_ch-1_p-9_s-5","chapterId":"yan-tie-lun_ch-1","passageId":"yan-tie-lun_ch-1_p-9","order":5,"canonicalText":"」","chunks":[]},{"id":"yan-tie-lun_ch-1_p-10_s-1","chapterId":"yan-tie-lun_ch-1","passageId":"yan-tie-lun_ch-1_p-10","order":1,"canonicalText":"文學曰：「國有沃野之饒而民不足於食者，工商盛而本業荒也；","chunks":[]},{"id":"yan-tie-lun_ch-1_p-10_s-2","chapterId":"yan-tie-lun_ch-1","passageId":"yan-tie-lun_ch-1_p-10","order":2,"canonicalText":"有山海之貨而民不足於財者，不務民用而求奇巧也。","chunks":[]},{"id":"yan-tie-lun_ch-1_p-10_s-3","chapterId":"yan-tie-lun_ch-1","passageId":"yan-tie-lun_ch-1_p-10","order":3,"canonicalText":"刺繡文飾，非救寒之服；","chunks":[]},{"id":"yan-tie-lun_ch-1_p-10_s-4","chapterId":"yan-tie-lun_ch-1","passageId":"yan-tie-lun_ch-1_p-10","order":4,"canonicalText":"雕琢刻鏤，非救飢之器。","chunks":[]},{"id":"yan-tie-lun_ch-1_p-10_s-5","chapterId":"yan-tie-lun_ch-1","passageId":"yan-tie-lun_ch-1_p-10","order":5,"canonicalText":"棄本逐末，民何得而不貧？","chunks":[]},{"id":"yan-tie-lun_ch-1_p-10_s-6","chapterId":"yan-tie-lun_ch-1","passageId":"yan-tie-lun_ch-1_p-10","order":6,"canonicalText":"」","chunks":[]},{"id":"yan-tie-lun_ch-1_p-11_s-1","chapterId":"yan-tie-lun_ch-1","passageId":"yan-tie-lun_ch-1_p-11","order":1,"canonicalText":"大夫曰：「往者，郡國諸侯各以其方物貢輸，往來煩雜，物多苦惡，或不償其費。","chunks":[]},{"id":"yan-tie-lun_ch-1_p-11_s-2","chapterId":"yan-tie-lun_ch-1","passageId":"yan-tie-lun_ch-1_p-11","order":2,"canonicalText":"故郡國置輸官以相給運，省天下之勞，此天下之利也。","chunks":[]},{"id":"yan-tie-lun_ch-1_p-11_s-3","chapterId":"yan-tie-lun_ch-1","passageId":"yan-tie-lun_ch-1_p-11","order":3,"canonicalText":"」","chunks":[]},{"id":"yan-tie-lun_ch-1_p-12_s-1","chapterId":"yan-tie-lun_ch-1","passageId":"yan-tie-lun_ch-1_p-12","order":1,"canonicalText":"文學曰：「古者之賦稅於民也，因其所工，不求所拙。","chunks":[]},{"id":"yan-tie-lun_ch-1_p-12_s-2","chapterId":"yan-tie-lun_ch-1","passageId":"yan-tie-lun_ch-1_p-12","order":2,"canonicalText":"農人納其穫，女工效其功。","chunks":[]},{"id":"yan-tie-lun_ch-1_p-12_s-3","chapterId":"yan-tie-lun_ch-1","passageId":"yan-tie-lun_ch-1_p-12","order":3,"canonicalText":"今釋其所有，責其所無，百姓賤賣所有以充官求，官吏乘其急而射其利，百姓安得不困？","chunks":[]},{"id":"yan-tie-lun_ch-1_p-12_s-4","chapterId":"yan-tie-lun_ch-1","passageId":"yan-tie-lun_ch-1_p-12","order":4,"canonicalText":"」","chunks":[]},{"id":"yan-tie-lun_ch-2_p-1_s-1","chapterId":"yan-tie-lun_ch-2","passageId":"yan-tie-lun_ch-2_p-1","order":1,"canonicalText":"大夫曰：「王者塞天財，禁關市，執準守時，以輕重御民。","chunks":[]},{"id":"yan-tie-lun_ch-2_p-1_s-2","chapterId":"yan-tie-lun_ch-2","passageId":"yan-tie-lun_ch-2_p-1","order":2,"canonicalText":"豐年歲登，則儲積以備乏絕；","chunks":[]},{"id":"yan-tie-lun_ch-2_p-1_s-3","chapterId":"yan-tie-lun_ch-2","passageId":"yan-tie-lun_ch-2_p-1","order":3,"canonicalText":"凶年惡歲，則發振以濟飢饉。","chunks":[]},{"id":"yan-tie-lun_ch-2_p-1_s-4","chapterId":"yan-tie-lun_ch-2","passageId":"yan-tie-lun_ch-2_p-1","order":4,"canonicalText":"此鹽、鐵、均輸之大用也。","chunks":[]},{"id":"yan-tie-lun_ch-2_p-1_s-5","chapterId":"yan-tie-lun_ch-2","passageId":"yan-tie-lun_ch-2_p-1","order":5,"canonicalText":"」","chunks":[]},{"id":"yan-tie-lun_ch-2_p-2_s-1","chapterId":"yan-tie-lun_ch-2","passageId":"yan-tie-lun_ch-2_p-2","order":1,"canonicalText":"文學曰：「古者，十一而稅，澤梁以時入而無禁，黎民鹹被南畝而不失其務。","chunks":[]},{"id":"yan-tie-lun_ch-2_p-2_s-2","chapterId":"yan-tie-lun_ch-2","passageId":"yan-tie-lun_ch-2_p-2","order":2,"canonicalText":"故三年耕而餘一年之蓄，九年耕而餘三年之蓄。","chunks":[]},{"id":"yan-tie-lun_ch-2_p-2_s-3","chapterId":"yan-tie-lun_ch-2","passageId":"yan-tie-lun_ch-2_p-2","order":3,"canonicalText":"今公家專利，與民相競，民失其本，安能有餘蓄？","chunks":[]},{"id":"yan-tie-lun_ch-2_p-2_s-4","chapterId":"yan-tie-lun_ch-2","passageId":"yan-tie-lun_ch-2_p-2","order":4,"canonicalText":"」","chunks":[]},{"id":"yan-tie-lun_ch-2_p-3_s-1","chapterId":"yan-tie-lun_ch-2","passageId":"yan-tie-lun_ch-2_p-3","order":1,"canonicalText":"大夫曰：「賢聖治家非一寶，富國非一道。","chunks":[]},{"id":"yan-tie-lun_ch-2_p-3_s-2","chapterId":"yan-tie-lun_ch-2","passageId":"yan-tie-lun_ch-2_p-3","order":2,"canonicalText":"昔管仲以權譎霸，而紀氏以強本亡。","chunks":[]},{"id":"yan-tie-lun_ch-2_p-3_s-3","chapterId":"yan-tie-lun_ch-2","passageId":"yan-tie-lun_ch-2_p-3","order":3,"canonicalText":"使治家養生必於農，則舜何為陶，伊尹何為庖？","chunks":[]},{"id":"yan-tie-lun_ch-2_p-3_s-4","chapterId":"yan-tie-lun_ch-2","passageId":"yan-tie-lun_ch-2_p-3","order":4,"canonicalText":"故本末相資，乃成大治。","chunks":[]},{"id":"yan-tie-lun_ch-2_p-3_s-5","chapterId":"yan-tie-lun_ch-2","passageId":"yan-tie-lun_ch-2_p-3","order":5,"canonicalText":"」","chunks":[]},{"id":"yan-tie-lun_ch-2_p-4_s-1","chapterId":"yan-tie-lun_ch-2","passageId":"yan-tie-lun_ch-2_p-4","order":1,"canonicalText":"文學曰：「古者，商通物而不豫，工緻牢而不偽。","chunks":[]},{"id":"yan-tie-lun_ch-2_p-4_s-2","chapterId":"yan-tie-lun_ch-2","passageId":"yan-tie-lun_ch-2_p-4","order":2,"canonicalText":"故君子耕稼田魚，其實一也。","chunks":[]},{"id":"yan-tie-lun_ch-2_p-4_s-3","chapterId":"yan-tie-lun_ch-2","passageId":"yan-tie-lun_ch-2_p-4","order":3,"canonicalText":"商則長詐，工則飾罵，皆以末技侵奪農功。","chunks":[]},{"id":"yan-tie-lun_ch-2_p-4_s-4","chapterId":"yan-tie-lun_ch-2","passageId":"yan-tie-lun_ch-2_p-4","order":4,"canonicalText":"故聖人抑末而崇本，非無商工，禁其過也。","chunks":[]},{"id":"yan-tie-lun_ch-2_p-4_s-5","chapterId":"yan-tie-lun_ch-2","passageId":"yan-tie-lun_ch-2_p-4","order":5,"canonicalText":"」","chunks":[]},{"id":"yan-tie-lun_ch-2_p-5_s-1","chapterId":"yan-tie-lun_ch-2","passageId":"yan-tie-lun_ch-2_p-5","order":1,"canonicalText":"大夫曰：「自京師東西南北，歷山川，經郡國，諸殷富大都，無非街衢五通，商賈之所湊，萬物之所殖。","chunks":[]},{"id":"yan-tie-lun_ch-2_p-5_s-2","chapterId":"yan-tie-lun_ch-2","passageId":"yan-tie-lun_ch-2_p-5","order":2,"canonicalText":"未聞有閉關市而致富強者也。","chunks":[]},{"id":"yan-tie-lun_ch-2_p-5_s-3","chapterId":"yan-tie-lun_ch-2","passageId":"yan-tie-lun_ch-2_p-5","order":3,"canonicalText":"」","chunks":[]},{"id":"yan-tie-lun_ch-2_p-6_s-1","chapterId":"yan-tie-lun_ch-2","passageId":"yan-tie-lun_ch-2_p-6","order":1,"canonicalText":"文學曰：「洪水滔天，而有禹之績，河水泛濫，而有宣房之功。","chunks":[]},{"id":"yan-tie-lun_ch-2_p-6_s-2","chapterId":"yan-tie-lun_ch-2","passageId":"yan-tie-lun_ch-2_p-6","order":2,"canonicalText":"商紂暴虐，而有孟津之謀，天下煩擾，而有文、景之治。","chunks":[]},{"id":"yan-tie-lun_ch-2_p-6_s-3","chapterId":"yan-tie-lun_ch-2","passageId":"yan-tie-lun_ch-2_p-6","order":3,"canonicalText":"今天下罷弊，正當修德息民，豈可以利為名而擾天下乎？","chunks":[]},{"id":"yan-tie-lun_ch-2_p-6_s-4","chapterId":"yan-tie-lun_ch-2","passageId":"yan-tie-lun_ch-2_p-6","order":4,"canonicalText":"」","chunks":[]},{"id":"yan-tie-lun_ch-3_p-1_s-1","chapterId":"yan-tie-lun_ch-3","passageId":"yan-tie-lun_ch-3_p-1","order":1,"canonicalText":"大夫曰：「燕之涿、薊，趙之邯鄲，魏之溫軹，韓之滎陽，齊之臨淄，楚之宛、陳，鄭之陽翟，三川之二週，富冠海內，皆天下之名都。","chunks":[]},{"id":"yan-tie-lun_ch-3_p-1_s-2","chapterId":"yan-tie-lun_ch-3","passageId":"yan-tie-lun_ch-3_p-1","order":2,"canonicalText":"非名山大川所生，乃商通物而後成也。","chunks":[]},{"id":"yan-tie-lun_ch-3_p-1_s-3","chapterId":"yan-tie-lun_ch-3","passageId":"yan-tie-lun_ch-3_p-1","order":3,"canonicalText":"」","chunks":[]},{"id":"yan-tie-lun_ch-3_p-2_s-1","chapterId":"yan-tie-lun_ch-3","passageId":"yan-tie-lun_ch-3_p-2","order":1,"canonicalText":"文學曰：「荊、揚南有桂林之饒，內有江、湖之利，左陵陽之金，右蜀、漢之材，伐木而樹穀，燔萊而耕田，足以自足。","chunks":[]},{"id":"yan-tie-lun_ch-3_p-2_s-2","chapterId":"yan-tie-lun_ch-3","passageId":"yan-tie-lun_ch-3_p-2","order":2,"canonicalText":"何必遠涉江湖，追逐末利乎？","chunks":[]},{"id":"yan-tie-lun_ch-3_p-2_s-3","chapterId":"yan-tie-lun_ch-3","passageId":"yan-tie-lun_ch-3_p-2","order":3,"canonicalText":"」","chunks":[]},{"id":"yan-tie-lun_ch-3_p-3_s-1","chapterId":"yan-tie-lun_ch-3","passageId":"yan-tie-lun_ch-3_p-3","order":1,"canonicalText":"大夫曰：「五行：東方木，而丹、章有金銅之山；","chunks":[]},{"id":"yan-tie-lun_ch-3_p-3_s-2","chapterId":"yan-tie-lun_ch-3","passageId":"yan-tie-lun_ch-3_p-3","order":2,"canonicalText":"南方火，而交趾有大海之川；","chunks":[]},{"id":"yan-tie-lun_ch-3_p-3_s-3","chapterId":"yan-tie-lun_ch-3","passageId":"yan-tie-lun_ch-3_p-3","order":3,"canonicalText":"西方金，而蜀、隴有名材之林；","chunks":[]},{"id":"yan-tie-lun_ch-3_p-3_s-4","chapterId":"yan-tie-lun_ch-3","passageId":"yan-tie-lun_ch-3_p-3","order":4,"canonicalText":"北方水，而幽、燕有旃裘之產。","chunks":[]},{"id":"yan-tie-lun_ch-3_p-3_s-5","chapterId":"yan-tie-lun_ch-3","passageId":"yan-tie-lun_ch-3_p-3","order":5,"canonicalText":"故因天地之利，通天下之用，王者之道也。","chunks":[]},{"id":"yan-tie-lun_ch-3_p-3_s-6","chapterId":"yan-tie-lun_ch-3","passageId":"yan-tie-lun_ch-3_p-3","order":6,"canonicalText":"」","chunks":[]},{"id":"yan-tie-lun_ch-3_p-4_s-1","chapterId":"yan-tie-lun_ch-3","passageId":"yan-tie-lun_ch-3_p-4","order":1,"canonicalText":"文學曰：「古者，採椽不斲，茅茨不翦，衣布褐，飯土硎，鑄金為鉏，埏埴為器，工不造奇巧，世不寶遠物。","chunks":[]},{"id":"yan-tie-lun_ch-3_p-4_s-2","chapterId":"yan-tie-lun_ch-3","passageId":"yan-tie-lun_ch-3_p-4","order":2,"canonicalText":"故民情純樸而教化行也。","chunks":[]},{"id":"yan-tie-lun_ch-3_p-4_s-3","chapterId":"yan-tie-lun_ch-3","passageId":"yan-tie-lun_ch-3_p-4","order":3,"canonicalText":"」","chunks":[]},{"id":"yan-tie-lun_ch-3_p-5_s-1","chapterId":"yan-tie-lun_ch-3","passageId":"yan-tie-lun_ch-3_p-5","order":1,"canonicalText":"大夫曰：「古者，宮室有度，輿服以庸；","chunks":[]},{"id":"yan-tie-lun_ch-3_p-5_s-2","chapterId":"yan-tie-lun_ch-3","passageId":"yan-tie-lun_ch-3_p-5","order":2,"canonicalText":"採椽茅茨，非先王之制也。","chunks":[]},{"id":"yan-tie-lun_ch-3_p-5_s-3","chapterId":"yan-tie-lun_ch-3","passageId":"yan-tie-lun_ch-3_p-5","order":3,"canonicalText":"君子節奢刺儉，儉則固。","chunks":[]},{"id":"yan-tie-lun_ch-3_p-5_s-4","chapterId":"yan-tie-lun_ch-3","passageId":"yan-tie-lun_ch-3_p-5","order":4,"canonicalText":"昔孫叔敖相楚，妻不衣帛，馬不食粟，然而楚國以霸。","chunks":[]},{"id":"yan-tie-lun_ch-3_p-5_s-5","chapterId":"yan-tie-lun_ch-3","passageId":"yan-tie-lun_ch-3_p-5","order":5,"canonicalText":"今因天下之利以充百用，何奢之有？","chunks":[]},{"id":"yan-tie-lun_ch-3_p-5_s-6","chapterId":"yan-tie-lun_ch-3","passageId":"yan-tie-lun_ch-3_p-5","order":6,"canonicalText":"」","chunks":[]},{"id":"yan-tie-lun_ch-3_p-6_s-1","chapterId":"yan-tie-lun_ch-3","passageId":"yan-tie-lun_ch-3_p-6","order":1,"canonicalText":"文學曰：「孟子云：『不違農時，穀不可勝食。","chunks":[]},{"id":"yan-tie-lun_ch-3_p-6_s-2","chapterId":"yan-tie-lun_ch-3","passageId":"yan-tie-lun_ch-3_p-6","order":2,"canonicalText":"蠶麻以時，布帛不可勝衣也。","chunks":[]},{"id":"yan-tie-lun_ch-3_p-6_s-3","chapterId":"yan-tie-lun_ch-3","passageId":"yan-tie-lun_ch-3_p-6","order":3,"canonicalText":"斧斤以時，材木不可勝用也。","chunks":[]},{"id":"yan-tie-lun_ch-3_p-6_s-4","chapterId":"yan-tie-lun_ch-3","passageId":"yan-tie-lun_ch-3_p-6","order":4,"canonicalText":"』今若崇末利而奪農時，雖有富商大賈，民何利焉？","chunks":[]},{"id":"yan-tie-lun_ch-3_p-6_s-5","chapterId":"yan-tie-lun_ch-3","passageId":"yan-tie-lun_ch-3_p-6","order":5,"canonicalText":"」","chunks":[]},{"id":"yan-tie-lun_ch-4_p-1_s-1","chapterId":"yan-tie-lun_ch-4","passageId":"yan-tie-lun_ch-4_p-1","order":1,"canonicalText":"大夫曰：「交幣通施，民事不及，物有所並也。","chunks":[]},{"id":"yan-tie-lun_ch-4_p-1_s-2","chapterId":"yan-tie-lun_ch-4","passageId":"yan-tie-lun_ch-4_p-1","order":2,"canonicalText":"計本量委，民有饑者，穀有所藏也。","chunks":[]},{"id":"yan-tie-lun_ch-4_p-1_s-3","chapterId":"yan-tie-lun_ch-4","passageId":"yan-tie-lun_ch-4_p-1","order":3,"canonicalText":"智者有百人之功，愚者有不全之負。","chunks":[]},{"id":"yan-tie-lun_ch-4_p-1_s-4","chapterId":"yan-tie-lun_ch-4","passageId":"yan-tie-lun_ch-4_p-1","order":4,"canonicalText":"故王者立幣以權輕重，齊萬物也。","chunks":[]},{"id":"yan-tie-lun_ch-4_p-1_s-5","chapterId":"yan-tie-lun_ch-4","passageId":"yan-tie-lun_ch-4_p-1","order":5,"canonicalText":"」","chunks":[]},{"id":"yan-tie-lun_ch-4_p-2_s-1","chapterId":"yan-tie-lun_ch-4","passageId":"yan-tie-lun_ch-4_p-2","order":1,"canonicalText":"文學曰：「古者，貴德而賤利，重義而輕財。","chunks":[]},{"id":"yan-tie-lun_ch-4_p-2_s-2","chapterId":"yan-tie-lun_ch-4","passageId":"yan-tie-lun_ch-4_p-2","order":2,"canonicalText":"三王之時，迭盛迭衰。","chunks":[]},{"id":"yan-tie-lun_ch-4_p-2_s-3","chapterId":"yan-tie-lun_ch-4","passageId":"yan-tie-lun_ch-4_p-2","order":3,"canonicalText":"衰則扶之，傾則定之。","chunks":[]},{"id":"yan-tie-lun_ch-4_p-2_s-4","chapterId":"yan-tie-lun_ch-4","passageId":"yan-tie-lun_ch-4_p-2","order":4,"canonicalText":"是以夏忠、殷質、周文，因時而化，未嘗聞以幣權天下也。","chunks":[]},{"id":"yan-tie-lun_ch-4_p-2_s-5","chapterId":"yan-tie-lun_ch-4","passageId":"yan-tie-lun_ch-4_p-2","order":5,"canonicalText":"」","chunks":[]},{"id":"yan-tie-lun_ch-4_p-3_s-1","chapterId":"yan-tie-lun_ch-4","passageId":"yan-tie-lun_ch-4_p-3","order":1,"canonicalText":"大夫曰：「湯、文繼衰，漢興乘弊。","chunks":[]},{"id":"yan-tie-lun_ch-4_p-3_s-2","chapterId":"yan-tie-lun_ch-4","passageId":"yan-tie-lun_ch-4_p-3","order":2,"canonicalText":"一質一文，非苟易常也。","chunks":[]},{"id":"yan-tie-lun_ch-4_p-3_s-3","chapterId":"yan-tie-lun_ch-4","passageId":"yan-tie-lun_ch-4_p-3","order":3,"canonicalText":"俗弊更法，非務變古也，亦所以救失扶衰也。","chunks":[]},{"id":"yan-tie-lun_ch-4_p-3_s-4","chapterId":"yan-tie-lun_ch-4","passageId":"yan-tie-lun_ch-4_p-3","order":4,"canonicalText":"故更造五銖錢，使民不得偽作，所以一法度而齊民心也。","chunks":[]},{"id":"yan-tie-lun_ch-4_p-3_s-5","chapterId":"yan-tie-lun_ch-4","passageId":"yan-tie-lun_ch-4_p-3","order":5,"canonicalText":"」","chunks":[]},{"id":"yan-tie-lun_ch-4_p-4_s-1","chapterId":"yan-tie-lun_ch-4","passageId":"yan-tie-lun_ch-4_p-4","order":1,"canonicalText":"文學曰：「古者，市朝而無刁幣，各以其所有易所無，抱布貿絲而已。","chunks":[]},{"id":"yan-tie-lun_ch-4_p-4_s-2","chapterId":"yan-tie-lun_ch-4","passageId":"yan-tie-lun_ch-4_p-4","order":2,"canonicalText":"後世即有龜貝金錢，交施之也。","chunks":[]},{"id":"yan-tie-lun_ch-4_p-4_s-3","chapterId":"yan-tie-lun_ch-4","passageId":"yan-tie-lun_ch-4_p-4","order":3,"canonicalText":"幣數更則民滋偽，法數變則民滋疑。","chunks":[]},{"id":"yan-tie-lun_ch-4_p-4_s-4","chapterId":"yan-tie-lun_ch-4","passageId":"yan-tie-lun_ch-4_p-4","order":4,"canonicalText":"故治民之道，在於安其心，不在於更其幣也。","chunks":[]},{"id":"yan-tie-lun_ch-4_p-4_s-5","chapterId":"yan-tie-lun_ch-4","passageId":"yan-tie-lun_ch-4_p-4","order":5,"canonicalText":"」","chunks":[]},{"id":"yan-tie-lun_ch-4_p-5_s-1","chapterId":"yan-tie-lun_ch-4","passageId":"yan-tie-lun_ch-4_p-5","order":1,"canonicalText":"大夫曰：「文帝之時，縱民得鑄錢、冶鐵、煮鹽。","chunks":[]},{"id":"yan-tie-lun_ch-4_p-5_s-2","chapterId":"yan-tie-lun_ch-4","passageId":"yan-tie-lun_ch-4_p-5","order":2,"canonicalText":"吳王擅鄣海澤，鄧通專西山。","chunks":[]},{"id":"yan-tie-lun_ch-4_p-5_s-3","chapterId":"yan-tie-lun_ch-4","passageId":"yan-tie-lun_ch-4_p-5","order":3,"canonicalText":"山東奸猾，鹹聚吳國，遂成七國之亂。","chunks":[]},{"id":"yan-tie-lun_ch-4_p-5_s-4","chapterId":"yan-tie-lun_ch-4","passageId":"yan-tie-lun_ch-4_p-5","order":4,"canonicalText":"故專利收幣，非徒富國也，所以裁抑兼併，杜絕禍亂之萌也。","chunks":[]},{"id":"yan-tie-lun_ch-4_p-5_s-5","chapterId":"yan-tie-lun_ch-4","passageId":"yan-tie-lun_ch-4_p-5","order":5,"canonicalText":"」","chunks":[]},{"id":"yan-tie-lun_ch-4_p-6_s-1","chapterId":"yan-tie-lun_ch-4","passageId":"yan-tie-lun_ch-4_p-6","order":1,"canonicalText":"文學曰：「往古，幣眾財通而民樂。","chunks":[]},{"id":"yan-tie-lun_ch-4_p-6_s-2","chapterId":"yan-tie-lun_ch-4","passageId":"yan-tie-lun_ch-4_p-6","order":2,"canonicalText":"其後，稍去舊幣，更行白金龜龍，民多巧新幣。","chunks":[]},{"id":"yan-tie-lun_ch-4_p-6_s-3","chapterId":"yan-tie-lun_ch-4","passageId":"yan-tie-lun_ch-4_p-6","order":3,"canonicalText":"幣數易而民益疑。","chunks":[]},{"id":"yan-tie-lun_ch-4_p-6_s-4","chapterId":"yan-tie-lun_ch-4","passageId":"yan-tie-lun_ch-4_p-6","order":4,"canonicalText":"文帝躬行節儉，寬刑薄賦，天下殷富。","chunks":[]},{"id":"yan-tie-lun_ch-4_p-6_s-5","chapterId":"yan-tie-lun_ch-4","passageId":"yan-tie-lun_ch-4_p-6","order":5,"canonicalText":"今言治者，不法文帝之清靜，而慕武帝之徵伐，此所謂捨本而逐末也。","chunks":[]},{"id":"yan-tie-lun_ch-4_p-6_s-6","chapterId":"yan-tie-lun_ch-4","passageId":"yan-tie-lun_ch-4_p-6","order":6,"canonicalText":"」","chunks":[]}]}') as WorkBundle
